class BookManagement {

    /*
    This is a class as managing books system, which supports to add and remove books from the inventory dict, view the inventory, and check the quantity of a specific book.
    */

    let inventory: HashMap<String, Int64>

    public init() {
        /*
        Initialize the inventory of Book Manager.
        */
        this.inventory = HashMap<String, Int64>()
    }

    public func add_book(title: String, quantity!: Int64 = 1): Unit {
        /*
        Add one or several books to inventory which is sorted by book title.
        :param title: String, the book title
        :param quantity: Int64, default value is 1.
        */
        if (quantity <= 0) {
            return
        }
        let current = this.inventory.get(title) ?? 0
        let newQty = current + quantity
        this.inventory.add(title, newQty)
    }

    public func remove_book(title: String, quantity: Int64): Unit {
        /*
        Remove one or several books from inventory which is sorted by book title.
        throw Exception("Invalid operation") while get invalid input.
        :param title: String, the book title
        :param quantity: Int64
        */
        if (quantity <= 0) {
            throw Exception("Invalid operation")
        }

        let opt = this.inventory.get(title)
        match (opt) {
            case Some<Int64>(cur) => {
                if (cur < quantity) {
                    throw Exception("Invalid operation")
                }
                let newQty = cur - quantity
                if (newQty == 0) {
                    this.inventory.remove(title)
                } else {
                    this.inventory.add(title, newQty)
                }
            }
            case _ => {
                throw Exception("Invalid operation")
            }
        }
    }

    public func view_inventory(): HashMap<String, Int64> {
        /*
        Get the inventory of the Book Management.
        :return this.inventory: HashMap<String, Int64>
        >>> bookManagement = BookManagement()
        >>> bookManagement.add_book("book1", quantity: 1)
        >>> bookManagement.add_book("book2", quantity: 1)
        >>> bookManagement.view_inventory()
        {'book1': 1, 'book2': 1}
        */
        this.inventory
    }

    public func view_book_quantity(title: String): Int64 {
        /*
        Get the quantity of a book.
        :param title: String, the title of the book.
        :return quantity: the quantity of this book title. return 0 when the title does not exist in this.inventory
        >>> bookManagement = BookManagement()
        >>> bookManagement.add_book("book1", quantity: 1)
        >>> bookManagement.view_book_quantity("book3")
        0
        */
        let opt = this.inventory.get(title)
        match (opt) {
            case Some<Int64>(v) => v
            case _ => 0
        }
    }
}

import std.collection.*

class BoyerMooreSearch {

    /*
    This is a class that implements the Boyer-Moore algorithm for string searching, which is used to find occurrences of a pattern within a given text.
    */

    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        /*
        Initializes the BoyerMooreSearch class with the given text and pattern.
        :param text: The text to be searched, String.
        :param pattern: The pattern to be searched for, String.
        */
        this.text = text
        this.pattern = pattern
        this.textLen = text.size
        this.patLen = pattern.size
    }

    public func match_in_pattern(char: String): Int64 {
        /*
        Finds the rightmost occurrence of a character in the pattern.
        :param char: The character to be searched for, String.
        :return: The index of the rightmost occurrence of the character in the pattern, Int64.
        >>> boyerMooreSearch = BoyerMooreSearch("ABAABA", "AB")
        >>> boyerMooreSearch.match_in_pattern("A")
        0
        */
        let charRunes = char.toRuneArray()
        if (charRunes.size == 0) {
            return -1
        }
        let target = charRunes[0]
        let pRunes = this.pattern.toRuneArray()
        var i: Int64 = this.patLen - 1
        while (i >= 0) {
            if (pRunes[i] == target) {
                return i
            }
            i = i - 1
        }
        return -1
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        /*
        Determines the position of the first dismatch between the pattern and the text.
        :param currentPos: The current position in the text, Int64.
        :return: The position of the first dismatch between the pattern and the text, Int64, otherwise -1.
        >>> boyerMooreSearch = BoyerMooreSearch("ABAABA", "ABC")
        >>> boyerMooreSearch.mismatch_in_text(0)
        2
        */
        let tRunes = this.text.toRuneArray()
        let pRunes = this.pattern.toRuneArray()

        var j: Int64 = this.patLen - 1
        while (j >= 0) {
            let trIdx = currentPos + j
            if (trIdx >= this.textLen) {
                return j
            }
            if (pRunes[j] == tRunes[trIdx]) {
                j = j - 1
            } else {
                return j
            }
        }
        return -1
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        /*
        Finds all occurrences of the pattern in the text.
        :return: A list of all positions of the pattern in the text, ArrayList<Int64>.
        >>> boyerMooreSearch = BoyerMooreSearch("ABAABA", "AB")
        >>> boyerMooreSearch.bad_character_heuristic()
        [0, 3]
        */
        let result = ArrayList<Int64>([])
        if (this.patLen == 0) {
            return result
        }
        if (this.patLen > this.textLen) {
            return result
        }

        let tRunes = this.text.toRuneArray()
        let pRunes = this.pattern.toRuneArray()

        func lastOccurInPattern(r: Rune): Int64 {
            var k: Int64 = this.patLen - 1
            while (k >= 0) {
                if (pRunes[k] == r) {
                    return k
                }
                k = k - 1
            }
            return -1
        }

        var i: Int64 = 0
        let limit: Int64 = this.textLen - this.patLen
        while (i <= limit) {
            let mm = this.mismatch_in_text(i)
            if (mm == -1) {
                // Match found at i
                result.add(i, at: result.size)
                if (i + this.patLen < this.textLen) {
                    let nextChar = tRunes[i + this.patLen]
                    let lo = lastOccurInPattern(nextChar)
                    i = i + (this.patLen - lo)
                } else {
                    i = i + 1
                }
            } else {
                let badChar = tRunes[i + mm]
                let lo = lastOccurInPattern(badChar)
                var shift: Int64 = mm - lo
                if (shift < 1) {
                    shift = 1
                }
                i = i + shift
            }
        }

        return result
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class Calculator {

    /*
    This is a class for a calculator, capable of performing basic arithmetic calculations on numerical expressions using the operators +, -, *, /, and ^ (exponentiation).
    */

    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        /*
        Initialize the operations performed by the five operators '+','-','*','/','^'
        */
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        /*
        Calculate the value of a given expression
        :param expression: String, given expression
        :return: If successful, returns the value of the expression; otherwise, returns None
        Example:
        >>> calculator = Calculator()
        >>> calculator.calculate("1+2-3")
        0.0
        */

        var operand_stack = ArrayList<Float64>()
        var operator_stack = ArrayList<String>()

        let runes = expression.toRuneArray()
        var i: Int64 = 0
        var expectOperand: Bool = true

        while (i < runes.size) {
            let ch = runes[i]

            // Skip spaces
            if (ch == r' ') {
                i = i + 1
                continue
            }

            if (expectOperand) {
                // Parse optional unary sign
                var sign: Float64 = 1.0
                if (ch == r'+') {
                    i = i + 1
                } else if (ch == r'-') {
                    sign = -1.0
                    i = i + 1
                }

                // After sign, parse number (digits with optional fractional part)
                var hasDigits: Bool = false

                var intVal: Float64 = 0.0
                while (i < runes.size && this.isDigit(runes[i])) {
                    intVal = intVal * 10.0 + this.digitToFloat(runes[i])
                    i = i + 1
                    hasDigits = true
                }

                var fracVal: Float64 = 0.0
                var fracDiv: Float64 = 1.0
                if (i < runes.size && runes[i] == r'.') {
                    i = i + 1
                    var fracHasDigits: Bool = false
                    while (i < runes.size && this.isDigit(runes[i])) {
                        fracVal = fracVal * 10.0 + this.digitToFloat(runes[i])
                        fracDiv = fracDiv * 10.0
                        i = i + 1
                        fracHasDigits = true
                    }
                    if (fracHasDigits) {
                        hasDigits = true
                    }
                }

                if (!hasDigits) {
                    return None<Float64>
                }

                let value: Float64 = sign * (intVal + (fracVal / fracDiv))
                operand_stack.add(value, at: operand_stack.size)
                expectOperand = false
            } else {
                // Expecting an operator
                var opStr: String = ""
                if (ch == r'+') {
                    opStr = "+"
                } else if (ch == r'-') {
                    opStr = "-"
                } else if (ch == r'*') {
                    opStr = "*"
                } else if (ch == r'/') {
                    opStr = "/"
                } else if (ch == r'^') {
                    opStr = "^"
                } else if (ch == r' ') {
                    i = i + 1
                    continue
                } else {
                    // Invalid character where operator expected
                    return None<Float64>
                }
                i = i + 1

                // Apply previous operators respecting precedence and right-associativity of ^
                while (operator_stack.size > 0) {
                    let topIdx = operator_stack.size - 1
                    let topOp = operator_stack[topIdx]
                    let pTop = this.precedence(topOp)
                    let pCur = this.precedence(opStr)

                    if (pTop > pCur || (pTop == pCur && opStr != "^")) {
                        let updated = this.apply_operator(operand_stack, operator_stack)
                        operand_stack = updated[0]
                        operator_stack = updated[1]
                    } else {
                        break
                    }
                }

                operator_stack.add(opStr, at: operator_stack.size)
                expectOperand = true
            }
        }

        // Expression shouldn't end expecting an operand
        if (expectOperand) {
            return None<Float64>
        }

        // Apply remaining operators
        while (operator_stack.size > 0) {
            let updated = this.apply_operator(operand_stack, operator_stack)
            operand_stack = updated[0]
            operator_stack = updated[1]
        }

        if (operand_stack.size == 1) {
            return Some<Float64>(operand_stack[0])
        } else {
            return None<Float64>
        }
    }

    public func precedence(op: String): Int64 {
        /*
        Returns the priority of the specified operator, where the higher the priority, the greater the assignment.
        '^' > ('/' and '*') > ('+' and '-')
        */
        if (op == "+" || op == "-") {
            return 1
        } else if (op == "*" || op == "/") {
            return 2
        } else if (op == "^") {
            return 3
        } else {
            return 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        /*
        Use the operator at the top of the operator stack to perform the operation on the two numbers at the top of the operand stack,
        and store the result on the top of the operand stack.
        :param operand_stack: ArrayList<Float64>
        :param operator_stack: ArrayList<String>
        :return: the updated operand_stack and operator_stack
        */
        if (operator_stack.size == 0 || operand_stack.size < 2) {
            return (operand_stack, operator_stack)
        }

        let opIdx = operator_stack.size - 1
        let op = operator_stack[opIdx]
        operator_stack.remove(at: opIdx)

        let bIdx = operand_stack.size - 1
        let b = operand_stack[bIdx]
        operand_stack.remove(at: bIdx)

        let aIdx = operand_stack.size - 1
        let a = operand_stack[aIdx]
        operand_stack.remove(at: aIdx)

        let f = operators[op]
        let res = f(a, b)
        operand_stack.add(res, at: operand_stack.size)

        return (operand_stack, operator_stack)
    }

    // Helpers

    func isDigit(ch: Rune): Bool {
        return ch == r'0' || ch == r'1' || ch == r'2' || ch == r'3' || ch == r'4' ||
               ch == r'5' || ch == r'6' || ch == r'7' || ch == r'8' || ch == r'9'
    }

    func digitToFloat(ch: Rune): Float64 {
        match (ch) {
            case r'0' => 0.0
            case r'1' => 1.0
            case r'2' => 2.0
            case r'3' => 3.0
            case r'4' => 4.0
            case r'5' => 5.0
            case r'6' => 6.0
            case r'7' => 7.0
            case r'8' => 8.0
            case r'9' => 9.0
            case _ => 0.0
        }
    }
}

