class CalendarUtil {

    /*
    This is a class as CalendarUtil that provides functionalities to manage calendar events, schedule appointments, and perform conflict checks.
    */

    let events: ArrayList<Event>

    public init() {
        /*
        Initialize the calendar with an empty list of events.
        */
        this.events = ArrayList<Event>()
    }

    public func add_event(event: Event): Unit {
        /*
        Add an event to the calendar.
        */
        this.events.add(event, at: this.events.size)
    }

    public func remove_event(event: Event): Unit {
        /*
        Remove an event from the calendar.
        */
        for (i in 0..this.events.size) {
            if (this.events[i] == event) {
                this.events.remove(at: i)
                break
            }
        }
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        /*
        Get all events on a given date (by year/month/day).
        */
        let result = ArrayList<Event>()
        for (i in 0..this.events.size) {
            let e = this.events[i]
            if (e.date.year == date.year && e.date.month == date.month && e.date.dayOfMonth == date.dayOfMonth) {
                result.add(e, at: result.size)
            }
        }
        return result
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        /*
        Check if the calendar is available for a given time slot.
        A conflict exists if any event overlaps with [start_time, end_time).
        */
        for (i in 0..this.events.size) {
            let e = this.events[i]
            // Overlap condition: start_time < e.end_time && end_time > e.start_time
            if (start_time < e.end_time && end_time > e.start_time) {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        /*
        Get all available time slots on a given date.
        The day range is [00:00 of date, 00:00 of next day).
        */
        let day_start = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 0, minute: 0)
        let day_end = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth + 1, hour: 0, minute: 0)

        // Gather and sort events on the given date by start_time
        let day_events = this.get_events(date)
        if (day_events.size > 1) {
            let key = { i: Event => i.start_time }
            sort(day_events, key: key)
        }

        let slots = ArrayList<(DateTime, DateTime)>()
        var cursor: DateTime = day_start

        for (i in 0..day_events.size) {
            let e = day_events[i]
            if (e.start_time > cursor) {
                slots.add((cursor, e.start_time), at: slots.size)
            }
            if (e.end_time > cursor) {
                cursor = e.end_time
            }
        }

        if (cursor < day_end) {
            slots.add((cursor, day_end), at: slots.size)
        }

        return slots
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        /*
        Get the next num_events upcoming events from now.
        */
        let now = DateTime.now()
        let upcoming = ArrayList<Event>()

        for (i in 0..this.events.size) {
            let e = this.events[i]
            if (e.start_time >= now) {
                upcoming.add(e, at: upcoming.size)
            }
        }

        if (upcoming.size > 1) {
            let key = { i: Event => i.start_time }
            sort(upcoming, key: key)
        }

        let result = ArrayList<Event>()
        let limit: Int64 = if (num_events < upcoming.size) { num_events } else { upcoming.size }
        for (i in 0..limit) {
            result.add(upcoming[i], at: result.size)
        }

        return result
    }
}

