class CamelCaseMap {

    /*
    This is a custom class that allows keys to be in camel case style by converting them from underscore style, which provides dictionary-like functionality.
    */

    let _data: HashMap<String, Any>

    public init() {
        /*
        Initialize data to an empty dictionary
        */
        _data = HashMap<String, Any>()
    }

    public func __getitem__(key: String): Any {
        /*
        Return the value corresponding to the key
        :param key:String
        :return:Any,the value corresponding to the key
        */
        let camelKey = CamelCaseMap._to_camel_case(key)
        let v = _data.get(camelKey).getOrThrow()
        return v
    }

    public func __setitem__(key: String, value: Any): Unit {
        /*
        Set the value corresponding to the key to the specified value
        :param key:String
        :param value:Any, the specified value
        :return:Unit
        */
        let camelKey = CamelCaseMap._to_camel_case(key)
        _data.add(camelKey, value)
    }

    public func __delitem__(key: String): Unit {
        /*
        Delete the value corresponding to the key
        :param key:String
        :return:Unit
        */
        let camelKey = CamelCaseMap._to_camel_case(key)
        _data.remove(camelKey)
    }

    public func __len__(): Int64 {
        /*
        Returns the length of the own data
        :return:Int64, length of data
        */
        return _data.size
    }

    public func _convert_key(key: Any): Any {
        /*
        convert key string into camel case
        If key is not String type, return key directly
        :param key:Any
        :return:Any, converted key string
        */
        let sOpt: ?String = key as String
        match (sOpt) {
            case Some<String>(s) => {
                return CamelCaseMap._to_camel_case(s)
            }
            case None<String> => {
                return key
            }
        }
    }

    public static func _to_camel_case(key: String): String {
        /*
        convert key string into camel case
        :param key:String
        :return:String, converted key string
        e.g. "first_name" -> "firstName"
        */
        // Helper to uppercase ASCII lowercase letters
        func toUpper(c: Rune): Rune {
            match (c) {
                case r'a' => r'A'
                case r'b' => r'B'
                case r'c' => r'C'
                case r'd' => r'D'
                case r'e' => r'E'
                case r'f' => r'F'
                case r'g' => r'G'
                case r'h' => r'H'
                case r'i' => r'I'
                case r'j' => r'J'
                case r'k' => r'K'
                case r'l' => r'L'
                case r'm' => r'M'
                case r'n' => r'N'
                case r'o' => r'O'
                case r'p' => r'P'
                case r'q' => r'Q'
                case r'r' => r'R'
                case r's' => r'S'
                case r't' => r'T'
                case r'u' => r'U'
                case r'v' => r'V'
                case r'w' => r'W'
                case r'x' => r'X'
                case r'y' => r'Y'
                case r'z' => r'Z'
                case _ => c
            }
        }

        let runes: Array<Rune> = key.toRuneArray()
        var res: String = ""
        var upperNext: Bool = false
        for (i in 0..runes.size) {
            let ch: Rune = runes[i]
            if (ch == r'_') {
                upperNext = true
            } else {
                if (upperNext) {
                    let uch: Rune = toUpper(ch)
                    res = "${res}${uch}"
                    upperNext = false
                } else {
                    res = "${res}${ch}"
                }
            }
        }
        return res
    }
}

