func timeCompare(a: String, b: String): Int64 {
    // Lexicographic compare for fixed-format "yyyy/MM/dd HH:mm"
    let ra = a.toRuneArray()
    let rb = b.toRuneArray()
    let n = if (ra.size < rb.size) { ra.size } else { rb.size }
    for (i in 0..n) {
        let ca = ra[i]
        let cb = rb[i]
        if (ca == cb) {
            continue
        } else {
            return if (ca < cb) { -1 } else { 1 }
        }
    }
    if (ra.size == rb.size) {
        return 0
    } else {
        return if (ra.size < rb.size) { -1 } else { 1 }
    }
}

