class DataStatistics2 {

    /*
    This is a class for performing data statistics, supporting to get the sum, minimum, maximum, variance, standard deviation, and correlation of a given dataset.
    */

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        /*
        Initialize Data List
        :param data:ArrayList<Float64>
        */
        this.data = data
    }

    public func get_sum(): Float64 {
        /*
        Calculate the sum of data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_sum()
        10.0
        */
        var s: Float64 = 0.0
        for (i in 0..this.data.size) {
            s = s + this.data[i]
        }
        return s
    }

    public func get_min(): Float64 {
        /*
        Calculate the minimum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_min()
        1.0
        */
        if (this.data.size == 0) {
            return 0.0
        }
        var m: Float64 = this.data[0]
        for (i in 1..this.data.size) {
            let v = this.data[i]
            if (v < m) {
                m = v
            }
        }
        return m
    }

    public func get_max(): Float64 {
        /*
        Calculate the maximum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_max()
        4.0
        */
        if (this.data.size == 0) {
            return 0.0
        }
        var m: Float64 = this.data[0]
        for (i in 1..this.data.size) {
            let v = this.data[i]
            if (v > m) {
                m = v
            }
        }
        return m
    }

    public func get_variance(): Float64 {
        /*
        Calculate variance, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_variance()
        1.25
        */
        let n = this.data.size
        if (n == 0) {
            return 0.0
        }
        var sum: Float64 = 0.0
        var cnt: Float64 = 0.0
        for (i in 0..n) {
            sum = sum + this.data[i]
            cnt = cnt + 1.0
        }
        let mean = sum / cnt
        var acc: Float64 = 0.0
        for (i in 0..n) {
            let d = this.data[i] - mean
            acc = acc + d * d
        }
        let var_pop = acc / cnt
        return round2(var_pop)
    }

    public func get_std_deviation(): Float64 {
        /*
        Calculate standard deviation, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_std_deviation()
        1.12
        */
        let n = this.data.size
        if (n == 0) {
            return 0.0
        }
        var sum: Float64 = 0.0
        var cnt: Float64 = 0.0
        for (i in 0..n) {
            sum = sum + this.data[i]
            cnt = cnt + 1.0
        }
        let mean = sum / cnt
        var acc: Float64 = 0.0
        for (i in 0..n) {
            let d = this.data[i] - mean
            acc = acc + d * d
        }
        let var_pop = acc / cnt
        let sd = sqrt(var_pop)
        return round2(sd)
    }

    public func get_correlation(): Float64 {
        /*
        Calculate correlation
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_correlation()
        1.0
        */
        let n = this.data.size
        if (n == 0) {
            return 0.0
        }

        // Compute means of x = 1,2,...,n and y = data
        var sumX: Float64 = 0.0
        var sumY: Float64 = 0.0
        var cnt: Float64 = 0.0
        var xi: Float64 = 1.0
        for (i in 0..n) {
            sumX = sumX + xi
            sumY = sumY + this.data[i]
            cnt = cnt + 1.0
            xi = xi + 1.0
        }
        let meanX = sumX / cnt
        let meanY = sumY / cnt

        // Numerator and denominators
        var num: Float64 = 0.0
        var denX: Float64 = 0.0
        var denY: Float64 = 0.0
        xi = 1.0
        for (i in 0..n) {
            let dx = xi - meanX
            let dy = this.data[i] - meanY
            num = num + dx * dy
            denX = denX + dx * dx
            denY = denY + dy * dy
            xi = xi + 1.0
        }

        let denom = sqrt(denX) * sqrt(denY)
        if (denom == 0.0) {
            return 0.0
        }
        return num / denom
    }

    private func round2(x: Float64): Float64 {
        return round(x * 100.0) / 100.0
    }
}

import std.collection.*
import std.math.*

class DataStatistics4 {

    /*
    This is a class that performs advanced mathematical calculations and statistics, including correlation coefficient, skewness, kurtosis, and probability density function (PDF) for a normal distribution.
    */

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        /*
        Calculate the correlation coefficient of two sets of data.
        :param data1: The first set of data,ArrayList<Float64>.
        :param data2: The second set of data,ArrayList<Float64>.
        :return: The correlation coefficient, Float64.
        >>> DataStatistics4.correlation_coefficient(ArrayList<Float64>([1.0, 2.0, 3.0]), ArrayList<Float64>([4.0, 5.0, 6.0]))
        0.9999999999999998

        */
        if (data1.size == 0 || data2.size == 0 || data1.size != data2.size) {
            return 0.0
        }

        var sumx: Float64 = 0.0
        var sumy: Float64 = 0.0
        var n_f: Float64 = 0.0
        for (i in 0..data1.size) {
            sumx += data1[i]
            sumy += data2[i]
            n_f += 1.0
        }
        let meanx = sumx / n_f
        let meany = sumy / n_f

        var sxx: Float64 = 0.0
        var syy: Float64 = 0.0
        var sxy: Float64 = 0.0
        for (i in 0..data1.size) {
            let dx = data1[i] - meanx
            let dy = data2[i] - meany
            sxx += dx * dx
            syy += dy * dy
            sxy += dx * dy
        }

        let denom = sqrt(sxx * syy)
        if (denom == 0.0) {
            return 0.0
        }
        return sxy / denom
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        /*
        Calculate the skewness of a set of data.
        :param data: The input data list, ArrayList<Float64>.
        :return: The skewness, Float64.
        >>> DataStatistics4.skewness(ArrayList<Float64>([1.0, 2.0, 5.0]))
        2.3760224064818463

        */
        if (data.size < 3) {
            return 0.0
        }

        var sum: Float64 = 0.0
        var n_f: Float64 = 0.0
        for (i in 0..data.size) {
            sum += data[i]
            n_f += 1.0
        }
        let mean = sum / n_f

        var sum2: Float64 = 0.0
        var sum3: Float64 = 0.0
        for (i in 0..data.size) {
            let d = data[i] - mean
            let d2 = d * d
            sum2 += d2
            sum3 += d2 * d
        }

        let m2 = sum2 / n_f
        if (m2 == 0.0) {
            return 0.0
        }
        let m2_3_2 = sqrt(m2) * m2
        let factor = n_f / ((n_f - 1.0) * (n_f - 2.0))
        return factor * (sum3 / m2_3_2)
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        /*
        Calculate the kurtosis of a set of data.
        :param data: The input data list, ArrayList<Float64>.
        :return: The kurtosis, Float64.
        >>> DataStatistics4.kurtosis(ArrayList<Float64>([1.0, 2.0, 5.0]))
        -1.5000000000000007

        */
        if (data.size == 0) {
            return 0.0
        }

        var sum: Float64 = 0.0
        var n_f: Float64 = 0.0
        for (i in 0..data.size) {
            sum += data[i]
            n_f += 1.0
        }
        let mean = sum / n_f

        var sum2: Float64 = 0.0
        var sum4: Float64 = 0.0
        for (i in 0..data.size) {
            let d = data[i] - mean
            let d2 = d * d
            sum2 += d2
            sum4 += d2 * d2
        }

        let m2 = sum2 / n_f
        if (m2 == 0.0) {
            return 0.0
        }
        let m4 = sum4 / n_f
        return (m4 / (m2 * m2)) - 3.0
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        /*
        Calculate the probability density function (PDF) of a set of data under a normal distribution.
        :param data: The input data list, ArrayList<Float64>.
        :param mu: The mean of the normal distribution, Float64.
        :param sigma: The standard deviation of the normal distribution, Float64.
        :return: The probability density function (PDF), ArrayList<Float64>.
        >>> DataStatistics4.pdf(ArrayList<Float64>([1.0, 2.0, 3.0]), 1.0, 1.0)
        [0.3989422804014327, 0.24197072451914337, 0.05399096651318806]

        */
        let pi: Float64 = 3.141592653589793
        let coef = 1.0 / (sigma * sqrt(2.0 * pi))
        var res = ArrayList<Float64>([])
        for (i in 0..data.size) {
            let x = data[i]
            let z = (x - mu) / sigma
            let val = coef * exp(-0.5 * z * z)
            res.add(val, at: res.size)
        }
        return res
    }
}

import std.collection.*

class DecryptionUtils {

    /*
    This is a class that provides methods for decryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the decryption utility with a key.
        :param key: The key to use for decryption,String.
        */
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        /*
        Deciphers the given ciphertext using the Caesar cipher
        :param ciphertext: The ciphertext to decipher,String.
        :param shift: The shift to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.caesar_decipher('ifmmp', 1)
        'hello'
        */
        let lowerStr: String = "abcdefghijklmnopqrstuvwxyz"
        let upperStr: String = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        let lower: Array<Rune> = lowerStr.toRuneArray()
        let upper: Array<Rune> = upperStr.toRuneArray()

        let s: Int64 = this.mod(shift, 26)

        let arr: Array<Rune> = ciphertext.toRuneArray()
        let n: Int64 = arr.size

        var res: String = ""
        for (i in 0..n) {
            let c: Rune = arr[i]
            let li: Int64 = this.findIndexIn(lower, c)
            if (li >= 0) {
                let ni: Int64 = this.mod(li - s, 26)
                let nc: Rune = lower[ni]
                res = "${res}${nc}"
            } else {
                let ui: Int64 = this.findIndexIn(upper, c)
                if (ui >= 0) {
                    let ni: Int64 = this.mod(ui - s, 26)
                    let nc: Rune = upper[ni]
                    res = "${res}${nc}"
                } else {
                    res = "${res}${c}"
                }
            }
        }
        return res
    }

    public func vigenere_decipher(ciphertext: String): String {
        /*
        Deciphers the given ciphertext using the Vigenere cipher
        :param ciphertext: The ciphertext to decipher,String.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.vigenere_decipher('ifmmp')
        'ybocl'
        */
        let keyArr: Array<Rune> = this.key.toRuneArray()
        let keyLen: Int64 = keyArr.size
        if (keyLen == 0) {
            return ciphertext
        }

        let lowerStr: String = "abcdefghijklmnopqrstuvwxyz"
        let upperStr: String = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        let lower: Array<Rune> = lowerStr.toRuneArray()
        let upper: Array<Rune> = upperStr.toRuneArray()

        let textArr: Array<Rune> = ciphertext.toRuneArray()
        let n: Int64 = textArr.size

        var res: String = ""
        var j: Int64 = 0  // index into key (advances only for letters in ciphertext)

        for (i in 0..n) {
            let c: Rune = textArr[i]
            let li: Int64 = this.findIndexIn(lower, c)
            let ui: Int64 = this.findIndexIn(upper, c)

            if (li >= 0 || ui >= 0) {
                // Find next letter in key to determine shift
                var s: Int64 = 0
                while (true) {
                    let kr: Rune = keyArr[this.mod(j, keyLen)]
                    let kli: Int64 = this.findIndexIn(lower, kr)
                    let kui: Int64 = this.findIndexIn(upper, kr)
                    if (kli >= 0) {
                        s = kli
                        j = j + 1
                        break
                    } else if (kui >= 0) {
                        s = kui
                        j = j + 1
                        break
                    } else {
                        // skip non-letter key characters
                        j = j + 1
                    }
                }

                if (li >= 0) {
                    let ni: Int64 = this.mod(li - s, 26)
                    let nc: Rune = lower[ni]
                    res = "${res}${nc}"
                } else {
                    let ni: Int64 = this.mod(ui - s, 26)
                    let nc: Rune = upper[ni]
                    res = "${res}${nc}"
                }
            } else {
                // Non-letter: keep as-is; do not advance key index
                res = "${res}${c}"
            }
        }
        return res
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        /*
        Deciphers the given ciphertext using the Rail Fence cipher
        :param encrypted_text: The ciphertext to decipher,String.
        :param rails: The number of rails to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.rail_fence_decipher('Hoo!el,Wrdl l', 3)
        'Hello, World!'
        */
        let enc: Array<Rune> = encrypted_text.toRuneArray()
        let n: Int64 = enc.size

        if (rails <= 1 || rails >= n) {
            return encrypted_text
        }

        // Build the rail index pattern for each character position
        var railIdxs: ArrayList<Int64> = ArrayList<Int64>([])
        var counts: ArrayList<Int64> = ArrayList<Int64>([])
        for (r in 0..rails) {
            counts.add(0, at: r)
        }

        var r: Int64 = 0
        var dir: Int64 = 1  // 1 down, -1 up
        for (i in 0..n) {
            railIdxs.add(r, at: i)
            counts[r] = counts[r] + 1
            r = r + dir
            if (r == 0) {
                dir = 1
            } else if (r == rails - 1) {
                dir = -1
            }
        }

        // Slice the encrypted text into per-rail segments
        var perRail: ArrayList<ArrayList<Rune>> = ArrayList<ArrayList<Rune>>([])
        var pos: Int64 = 0
        for (ri in 0..rails) {
            let cnt: Int64 = counts[ri]
            var lst: ArrayList<Rune> = ArrayList<Rune>([])
            for (k in 0..cnt) {
                lst.add(enc[pos + k], at: k)
            }
            pos = pos + cnt
            perRail.add(lst, at: ri)
        }

        // Reconstruct plaintext by walking the rail pattern and taking the next rune from each rail
        var perRailPos: ArrayList<Int64> = ArrayList<Int64>([])
        for (ri in 0..rails) {
            perRailPos.add(0, at: ri)
        }

        var res: String = ""
        for (i in 0..n) {
            let ri: Int64 = railIdxs[i]
            let idxInRail: Int64 = perRailPos[ri]
            let ch: Rune = perRail[ri][idxInRail]
            perRailPos[ri] = idxInRail + 1
            res = "${res}${ch}"
        }

        return res
    }

    // Helpers

    private func mod(a: Int64, m: Int64): Int64 {
        let r: Int64 = a % m
        if (r < 0) {
            return r + m
        } else {
            return r
        }
    }

    private func findIndexIn(arr: Array<Rune>, target: Rune): Int64 {
        let n: Int64 = arr.size
        for (i in 0..n) {
            if (arr[i] == target) {
                return i
            }
        }
        return -1
    }
}

