class Interpolation {

    /*
    This is a class that implements the Linear interpolation operation of one-dimensional and two-dimensional data
    */

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        /*
        Linear interpolation of one-dimensional data
        :param x: The x-coordinate of the data point, ArrayList<Float64>.
        :param y: The y-coordinate of the data point, ArrayList<Float64>.
        :param x_interp: The x-coordinate of the interpolation point, ArrayList<Float64>.
        :return: The y-coordinate of the interpolation point, ArrayList<Float64>.
        >>> Interpolation.interpolate_1d(ArrayList<Float64>([1.0, 2.0, 3.0]), ArrayList<Float64>([1.0, 2.0, 3.0]), ArrayList<Float64>([1.5, 2.5]))
        [1.5, 2.5]
        */

        let n: Int64 = x.size
        let m: Int64 = x_interp.size
        let res = ArrayList<Float64>([])

        if (n < 2 || n != y.size) {
            // Invalid input; return empty result
            return res
        }

        for (k in 0..m) {
            let xi: Float64 = x_interp[k]
            let i: Int64 = Interpolation.find_interval(x, xi)

            let x0: Float64 = x[i]
            let x1: Float64 = x[i + 1]
            let y0: Float64 = y[i]
            let y1: Float64 = y[i + 1]

            let denom_x: Float64 = x1 - x0
            let t: Float64 = if (denom_x == 0.0) { 0.0 } else { (xi - x0) / denom_x }

            let yi: Float64 = y0 * (1.0 - t) + y1 * t
            res.add(yi, at: res.size)
        }

        return res
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        /*
        Linear interpolation of two-dimensional data
        :param x: The x-coordinate of the data point, ArrayList<Float64>.
        :param y: The y-coordinate of the data point, ArrayList<Float64>.
        :param z: The z-coordinate of the data point, ArrayList<ArrayList<Float64>>.
        :param x_interp: The x-coordinate of the interpolation point, ArrayList<Float64>.
        :param y_interp: The y-coordinate of the interpolation point, ArrayList<Float64>.
        :return: The z-coordinate of the interpolation point, ArrayList<Float64>.
        >>> let x = ArrayList<Float64>([1.0, 2.0, 3.0])
        >>> let y = ArrayList<Float64>([1.0, 2.0, 3.0])
        >>> let z = ArrayList<ArrayList<Float64>>([ArrayList<Float64>([1.0, 2.0, 3.0]), ArrayList<Float64>([4.0, 5.0, 6.0]), ArrayList<Float64>([7.0, 8.0, 9.0])])
        >>> let x_interp = ArrayList<Float64>([1.5, 2.5])
        >>> let y_interp = ArrayList<Float64>([1.5, 2.5])
        >>> let result = Interpolation.interpolate_2d(x, y, z, x_interp, y_interp)
        >>> result
        [3.0, 7.0]
        */

        let nx: Int64 = x.size
        let ny: Int64 = y.size
        let m: Int64 = x_interp.size
        let res = ArrayList<Float64>([])

        if (nx < 2 || ny < 2 || m != y_interp.size) {
            return res
        }

        for (k in 0..m) {
            let xi: Float64 = x_interp[k]
            let yi: Float64 = y_interp[k]

            let ix: Int64 = Interpolation.find_interval(x, xi)
            let iy: Int64 = Interpolation.find_interval(y, yi)

            let x0: Float64 = x[ix]
            let x1: Float64 = x[ix + 1]
            let y0: Float64 = y[iy]
            let y1: Float64 = y[iy + 1]

            let denom_x: Float64 = x1 - x0
            let denom_y: Float64 = y1 - y0
            let tx: Float64 = if (denom_x == 0.0) { 0.0 } else { (xi - x0) / denom_x }
            let ty: Float64 = if (denom_y == 0.0) { 0.0 } else { (yi - y0) / denom_y }

            let z00: Float64 = z[iy][ix]
            let z10: Float64 = z[iy][ix + 1]
            let z01: Float64 = z[iy + 1][ix]
            let z11: Float64 = z[iy + 1][ix + 1]

            let v: Float64 =
                z00 * (1.0 - tx) * (1.0 - ty) +
                z10 * tx * (1.0 - ty) +
                z01 * (1.0 - tx) * ty +
                z11 * tx * ty

            res.add(v, at: res.size)
        }

        return res
    }

    private static func find_interval(vals: ArrayList<Float64>, v: Float64): Int64 {
        let n: Int64 = vals.size
        if (n < 2) {
            return 0
        }

        if (v <= vals[0]) {
            return 0
        }
        if (v >= vals[n - 1]) {
            return n - 2
        }

        for (i in 0..(n - 1)) {
            if (vals[i] <= v && v <= vals[i + 1]) {
                return i
            }
        }
        // Fallback (should not reach here due to earlier bounds)
        return n - 2
    }
}

import std.collection.*

class IPAddress {

    /*
    This is a class to process IP Address, including validating, getting the octets and obtaining the binary representation of a valid IP address.
    */

    let ip_address: String

    public init(ip_address: String) {
        /*
        Initialize the IP address to the specified address
        :param ip_address:String
        */
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        /*
        Judge whether the IP address is valid, that is, whether the IP address is composed of four Decimal digits separated by '.'. Each digit is greater than or equal to 0 and less than or equal to 255
        :return: Bool
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.is_valid()
        true
        */
        let partsOpt = splitNumericOctets(this.ip_address)
        let parts = partsOpt ?? ArrayList<String>([])
        if (parts.size != 4) {
            false
        } else {
            for (i in 0..parts.size) {
                let po = parseOctet(parts[i])
                let val = po ?? -1
                if (val < 0) {
                    return false
                }
            }
            true
        }
    }

    public func get_octets(): ArrayList<String> {
        /*
        If the IP address is valid, the list of four decimal numbers separated by "." constituting the IP address is returned; otherwise, an empty list is returned
        :return: ArrayList<String>
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.get_octets()
        ["10", "10", "10", "10"]
        */
        let partsOpt = splitNumericOctets(this.ip_address)
        let parts = partsOpt ?? ArrayList<String>([])
        if (parts.size != 4) {
            ArrayList<String>([])
        } else {
            for (i in 0..parts.size) {
                let po = parseOctet(parts[i])
                let val = po ?? -1
                if (val < 0) {
                    return ArrayList<String>([])
                }
            }
            parts
        }
    }

    public func get_binary(): String {
        /*
        If the IP address is valid, return the binary form of the IP address; otherwise, return ''
        :return: String
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.get_binary()
        "00001010.00001010.00001010.00001010"
        */
        let partsOpt = splitNumericOctets(this.ip_address)
        let parts = partsOpt ?? ArrayList<String>([])
        if (parts.size != 4) {
            ""
        } else {
            var result: String = ""
            for (i in 0..parts.size) {
                let po = parseOctet(parts[i])
                let tmp = po ?? -1
                if (tmp < 0) {
                    return ""
                }
                var v: Int64 = tmp
                var seg: String = ""
                var p: Int64 = 128
                while (p > 0) {
                    if (v >= p) {
                        seg = "${seg}1"
                        v = v - p
                    } else {
                        seg = "${seg}0"
                    }
                    p = p / 2
                }
                if (i > 0) {
                    result = "${result}."
                }
                result = "${result}${seg}"
            }
            result
        }
    }

    // Helpers

    func splitNumericOctets(s: String): Option<ArrayList<String>> {
        var res = ArrayList<String>([])
        var cur: String = ""
        var curLen: Int64 = 0
        let runes = s.toRuneArray()
        for (i in 0..runes.size) {
            let ch = runes[i]
            if (ch == r'.') {
                if (curLen == 0) {
                    return None<ArrayList<String>>
                }
                res.add(cur, at: res.size)
                cur = ""
                curLen = 0
            } else {
                if (!isDigit(ch)) {
                    return None<ArrayList<String>>
                }
                cur = "${cur}${ch}"
                curLen = curLen + 1
            }
        }
        if (curLen == 0) {
            return None<ArrayList<String>>
        }
        res.add(cur, at: res.size)
        if (res.size != 4) {
            return None<ArrayList<String>>
        }
        Some<ArrayList<String>>(res)
    }

    func parseOctet(s: String): Option<Int64> {
        var v: Int64 = 0
        let runes = s.toRuneArray()
        for (i in 0..runes.size) {
            let ch = runes[i]
            let d = digitOf(ch)
            if (d < 0) {
                return None<Int64>
            }
            v = v * 10 + d
            if (v > 255) {
                return None<Int64>
            }
        }
        Some<Int64>(v)
    }

    func isDigit(ch: Rune): Bool {
        if (ch == r'0') { true }
        else if (ch == r'1') { true }
        else if (ch == r'2') { true }
        else if (ch == r'3') { true }
        else if (ch == r'4') { true }
        else if (ch == r'5') { true }
        else if (ch == r'6') { true }
        else if (ch == r'7') { true }
        else if (ch == r'8') { true }
        else if (ch == r'9') { true }
        else { false }
    }

    func digitOf(ch: Rune): Int64 {
        if (ch == r'0') { 0 }
        else if (ch == r'1') { 1 }
        else if (ch == r'2') { 2 }
        else if (ch == r'3') { 3 }
        else if (ch == r'4') { 4 }
        else if (ch == r'5') { 5 }
        else if (ch == r'6') { 6 }
        else if (ch == r'7') { 7 }
        else if (ch == r'8') { 8 }
        else if (ch == r'9') { 9 }
        else { -1 }
    }
}

