class IpUtil {

    /*
    This is a class as tool for ip that can be used to obtain the local IP address, validate its validity, and also provides the functionality to retrieve the corresponding hostname.
    */

    public static func is_valid_ipv4(ip_address: String): Bool {
        /*
        Check if the given IP address is a valid IPv4 address.
        :param ip_address: String, the IP address to check
        :return: Bool, true if the IP address is valid, false otherwise
        >>> IpUtil.is_valid_ipv4('192.168.0.123')
        true
        >>> IpUtil.is_valid_ipv4('256.0.0.0')
        false
        */
        let parsed = IPAddress.parse(ip_address)
        match (parsed) {
            case Some<IPAddress>(addr) => addr.isIPv4()
            case _ => false
        }
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        /*
        Check if the given IP address is a valid IPv6 address.
        :param ip_address:String, the IP address to check
        :return:Bool, true if the IP address is valid, false otherwise
        >>> IpUtil.is_valid_ipv6('2001:0db8:85a3:0000:0000:8a2e:0370:7334')
        true
        >>> IpUtil.is_valid_ipv6('2001:0db8:85a3:::8a2e:0370:7334')
        false
        */
        let parsed = IPAddress.parse(ip_address)
        match (parsed) {
            case Some<IPAddress>(addr) => addr.isIPv6()
            case _ => false
        }
    }

    public static func get_hostname(ip_address: String): Option<String> {
        /*
        Get the hostname associated with the given IP address.
        :param ip_address:String, the IP address to get the hostname for
        :return: String, the hostname associated with the IP address
        >>> IpUtil.get_hostname('110.242.68.3')
        'www.baidu.com'
        >>> IpUtil.get_hostname('10.0.0.1')
        None
        */
        let parsed = IPAddress.parse(ip_address)
        match (parsed) {
            case Some<IPAddress>(addr) => DNS.reverseLookup(addr)
            case _ => None<String>
        }
    }
}

import std.collection.*

interface Equatable<T> {
    operator func ==(that: T): Bool
    operator func !=(that: T): Bool
}

class Resume <: Equatable<Resume> {

    /*
    Represents a candidate's resume containing personal information, skills, and work experience.
    This class is used within the job marketplace system to store and manage applicant data.
    It conforms to the Equatable interface to allow comparison between resume instances.
    */

    let name: String
    let skills: ArrayList<String>
    let experience: String

    public init(name: String, skills: ArrayList<String>, experience: String) {
        this.name = name
        this.skills = skills
        this.experience = experience
    }

    public override operator func != (that: Resume): Bool {
        return this.name != that.name || this.skills != that.skills || this.experience != that.experience
    }

    public override operator func == (that: Resume): Bool {
        return this.name == that.name && this.skills == that.skills && this.experience == that.experience
    }
}

class JobListing <: Equatable<JobListing> {

    /*
    Represents a job listing posted by a company, including the job title, company name, and required skills.
    This class is used in the job marketplace to manage available positions.
    It conforms to the Equatable interface to allow comparison between job listings.
    */

    let job_title: String
    let company: String
    let requirements: ArrayList<String>

    public init(job_title: String, company: String, requirements: ArrayList<String>) {
        this.job_title = job_title
        this.company = company
        this.requirements = requirements
    }

    public override operator func != (that: JobListing): Bool {
        return this.job_title != that.job_title || this.company != that.company || this.requirements != that.requirements
    }

    public override operator func == (that: JobListing): Bool {
        return this.job_title == that.job_title && this.company == that.company && this.requirements == that.requirements
    }
}

class JobMarketplace {

    /*
    This is a class that provides functionalities to publish positions, remove positions, submit resumes, withdraw resumes, search for positions, and obtain candidate information.
    */

    let jobListings: ArrayList<JobListing>
    let resumes: ArrayList<Resume>

    public init() {
        this.jobListings = ArrayList<JobListing>()
        this.resumes = ArrayList<Resume>()
    }

    public func post_job(job_title: String, company: String, requirements: ArrayList<String>): Unit {
        let job = JobListing(job_title, company, requirements)
        this.jobListings.add(job, at: this.jobListings.size)
    }

    public func remove_job(job: JobListing): Unit {
        for (i in 0..this.jobListings.size) {
            if (this.jobListings[i] == job) {
                this.jobListings.remove(at: i)
                break
            }
        }
    }

    public func submit_resume(name: String, skills: ArrayList<String>, experience: String): Unit {
        let resume = Resume(name, skills, experience)
        this.resumes.add(resume, at: this.resumes.size)
    }

    public func withdraw_resume(resume: Resume): Unit {
        for (i in 0..this.resumes.size) {
            if (this.resumes[i] == resume) {
                this.resumes.remove(at: i)
                break
            }
        }
    }

    public func search_jobs(criteria: String): ArrayList<JobListing> {
        let result = ArrayList<JobListing>()
        for (i in 0..this.jobListings.size) {
            let job = this.jobListings[i]
            var matched: Bool = false
            for (j in 0..job.requirements.size) {
                if (job.requirements[j] == criteria) {
                    matched = true
                    break
                }
            }
            if (matched) {
                result.add(job, at: result.size)
            }
        }
        return result
    }

    public func get_job_applicants(job: JobListing): ArrayList<Resume> {
        let result = ArrayList<Resume>()
        for (i in 0..this.resumes.size) {
            let resume = this.resumes[i]
            if (JobMarketplace.matches_requirements(resume, job.requirements)) {
                result.add(resume, at: result.size)
            }
        }
        return result
    }

    public static func matches_requirements(resume: Resume, requirements: ArrayList<String>): Bool {
        for (i in 0..requirements.size) {
            let req = requirements[i]
            var found: Bool = false
            for (j in 0..resume.skills.size) {
                if (resume.skills[j] == req) {
                    found = true
                    break
                }
            }
            if (!found) {
                return false
            }
        }
        return true
    }
}

import std.collection.*

class KappaCalculator {

    /*
    This is a class as KappaCalculator, supporting to calculate Cohen's and Fleiss' kappa coefficient.
    */

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        // Handle empty or invalid input
        if (k <= 0 || testData.size == 0) {
            return 0.0
        }

        var n: Int64 = 0
        var diagSum: Int64 = 0

        // Prepare row and column sums
        var rowSums = ArrayList<Int64>([])
        var colSums = ArrayList<Int64>([])
        for (i in 0..k) {
            rowSums.add(0, at: i)
            colSums.add(0, at: i)
        }

        // Accumulate sums
        for (i in 0..k) {
            let row = testData[i]
            var rSum: Int64 = 0
            for (j in 0..k) {
                let v = row[j]
                rSum = rSum + v
                colSums[j] = colSums[j] + v
                if (i == j) {
                    diagSum = diagSum + v
                }
            }
            rowSums[i] = rSum
            n = n + rSum
        }

        if (n == 0) {
            return 0.0
        }

        let po: Float64 = (1.0 * diagSum) / (1.0 * n)

        var pe: Float64 = 0.0
        let nFloat: Float64 = 1.0 * n
        for (c in 0..k) {
            pe = pe + (1.0 * rowSums[c]) * (1.0 * colSums[c]) / (nFloat * nFloat)
        }

        let denom: Float64 = 1.0 - pe
        if (denom == 0.0) {
            return 0.0
        }
        return (po - pe) / denom
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        // Validate parameters
        if (N <= 0 || k <= 0 || n <= 1) {
            return 0.0
        }

        // Category totals across all items
        var catTotals = ArrayList<Int64>([])
        for (j in 0..k) {
            catTotals.add(0, at: j)
        }

        var sumPi: Float64 = 0.0
        let denomPerItem: Float64 = (1.0 * n) * (1.0 * (n - 1))

        // For each item, compute agreement and accumulate category totals
        for (i in 0..N) {
            let row = testData[i]
            var itemAgreeNumer: Int64 = 0
            for (j in 0..k) {
                let v = row[j]
                catTotals[j] = catTotals[j] + v
                itemAgreeNumer = itemAgreeNumer + (v * (v - 1))
            }
            let Pi: Float64 = (denomPerItem == 0.0) ? 0.0 : ((1.0 * itemAgreeNumer) / denomPerItem)
            sumPi = sumPi + Pi
        }

        let Pbar: Float64 = (1.0 * sumPi) / (1.0 * N)

        // Compute expected agreement
        let totalRatings: Float64 = (1.0 * N) * (1.0 * n)
        var PbarE: Float64 = 0.0
        for (j in 0..k) {
            let pj: Float64 = (1.0 * catTotals[j]) / totalRatings
            PbarE = PbarE + pj * pj
        }

        let denom: Float64 = 1.0 - PbarE
        if (denom == 0.0) {
            return 0.0
        }
        return (Pbar - PbarE) / denom
    }
}

import std.collection.*

class LongestWord {

    /*
    This is a class allows to add words to a list and find the longest word in a given sentence by comparing the words with the ones in the word list.
    */

    let word_list: ArrayList<String>

    public init() {
        /*
        Initialize a list of word.
        */
        this.word_list = ArrayList<String>()
    }

    public func add_word(word: String): Unit {
        /*
        append the input word into this.word_list
        :param word: String, input word
        */
        this.word_list.add(word, at: this.word_list.size)
    }

    public func find_longest_word(sentence: String): String {
        /*
        Remove punctuation marks and split a sentence into a list of word. Find the longest splited word that is in the this.word_list.
        Words are strictly case sensitive.
        :param sentence: a sentence String
        :return String: longest splited word that is in the this.word_list. return '' if this.word_list is empty.
        >>> longestWord = LongestWord()
        >>> longestWord.add_word('A')
        >>> longestWord.add_word('aM')
        >>> longestWord.find_longest_word('I am a student.')
        'a'
        */
        if (this.word_list.size == 0) {
            return ""
        }

        // Tokenize: keep continuous [A-Za-z0-9] as words, treat others as separators.
        let chars = sentence.toRuneArray()
        var tokens = ArrayList<String>()
        var current = ""

        func isAlphaNum(ch: Rune): Bool {
            if ((ch >= r'0' && ch <= r'9') || (ch >= r'A' && ch <= r'Z') || (ch >= r'a' && ch <= r'z')) {
                return true
            } else {
                return false
            }
        }

        for (i in 0..chars.size) {
            let ch = chars[i]
            if (isAlphaNum(ch)) {
                current = current + "${ch}"
            } else {
                if (current != "") {
                    tokens.add(current, at: tokens.size)
                    current = ""
                }
            }
        }
        if (current != "") {
            tokens.add(current, at: tokens.size)
        }

        func inWordList(w: String): Bool {
            for (j in 0..this.word_list.size) {
                if (this.word_list[j] == w) {
                    return true
                }
            }
            return false
        }

        var bestWord = ""
        var bestLen: Int64 = 0
        for (k in 0..tokens.size) {
            let w = tokens[k]
            if (inWordList(w)) {
                let l = w.toRuneArray().size
                if (l > bestLen) {
                    bestLen = l
                    bestWord = w
                }
            }
        }
        return bestWord
    }
}

import std.collection.*

class MahjongConnect {

    /*
    MahjongConnect is a class representing a game board for Mahjong Connect with features like creating the board, checking valid moves, finding paths, removing icons, and checking if the game is over.
    */

    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        /*
        initialize the board size and the icon list, create the game board
        :param BOARD_SIZE: list of two integer numbers, representing the number of rows and columns of the game board
        :param ICONS: list of String, representing the icons
        */
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = MahjongConnect.create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        create the game board with the given board size and icons
        :return: 2-dimensional list, the game board

        Note: This fills each row by repeating ICONS across columns, e.g. for 4x4 and ["a","b","c"]:
        [
          ["a","b","c","a"],
          ["a","b","c","a"],
          ["a","b","c","a"],
          ["a","b","c","a"]
        ]
        */
        let rows = BOARD_SIZE[0]
        let cols = BOARD_SIZE[1]

        var board = ArrayList<ArrayList<String>>([])
        for (r in 0..rows) {
            var row = ArrayList<String>([])
            for (c in 0..cols) {
                let icon = ICONS[c % ICONS.size]
                row.add(icon, at: row.size)
            }
            board.add(row, at: board.size)
        }
        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        /*
        check if the move of two icons is valid (i.e. positions are within the game board range, the two positions are not the same, the two positions have the same icon, and there is a valid path between the two positions)
        Positions are treated as (row, col).
        */
        let rows = this.BOARD_SIZE[0]
        let cols = this.BOARD_SIZE[1]

        let r1 = pos1[0]
        let c1 = pos1[1]
        let r2 = pos2[0]
        let c2 = pos2[1]

        // bounds check
        if (r1 < 0 || r1 >= rows || c1 < 0 || c1 >= cols) { return false }
        if (r2 < 0 || r2 >= rows || c2 < 0 || c2 >= cols) { return false }

        // not same position
        if (r1 == r2 && c1 == c2) { return false }

        let v1 = this.board[r1][c1]
        let v2 = this.board[r2][c2]

        // cannot select empty cells and icons must match
        if (v1 == " " || v2 == " ") { return false }
        if (v1 != v2) { return false }

        return this.has_path(pos1, pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        /*
        check if there is a path between two icons using at most 2 turns (3 straight segments).
        Movement allowed through empty spaces (" ") and into the destination cell. Orthogonal moves only.
        Positions are treated as (row, col).
        */
        let rows = this.BOARD_SIZE[0]
        let cols = this.BOARD_SIZE[1]

        let r1 = pos1[0]
        let c1 = pos1[1]
        let r2 = pos2[0]
        let c2 = pos2[1]

        // quick acceptance if adjacent and not blocked
        if (r1 == r2 && c1 == c2) { return false }

        // Directions: 0 up, 1 down, 2 left, 3 right
        let dr = [-1, 1, 0, 0]
        let dc = [0, 0, -1, 1]

        // BFS queue of states: (row, col, dir, turns)
        var q = ArrayList<(Int64, Int64, Int64, Int64)>([])
        var head: Int64 = 0

        // visited set of "r,c,dir,turns"
        var visited = HashSet<String>([])

        func add_state(r: Int64, c: Int64, dir: Int64, turns: Int64): Unit {
            let key = "${r},${c},${dir},${turns}"
            if (!visited.contains(key)) {
                visited.add(key)
                q.add((r, c, dir, turns), at: q.size)
            }
        }

        // seed: from start, we can begin in any direction with 0 turns
        for (d in 0..4) {
            add_state(r1, c1, d, 0)
        }

        while (head < q.size) {
            let state = q[head]
            head = head + 1

            let cr = state[0]
            let cc = state[1]
            let dir = state[2]
            let turns = state[3]

            // try stepping 1 cell in each direction
            for (nd in 0..4) {
                let nr = cr + dr[nd]
                let nc = cc + dc[nd]

                var nturns = turns
                if (nd != dir) {
                    nturns = nturns + 1
                }
                if (nturns > 2) {
                    continue
                }

                // bounds
                if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                    continue
                }

                // If we reached destination, path is valid
                if (nr == r2 && nc == c2) {
                    return true
                }

                // Can traverse only through empty spaces
                if (this.board[nr][nc] == " ") {
                    add_state(nr, nc, nd, nturns)
                }
            }
        }

        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        /*
        check if the position is in the visited list
        :param visited: list of position tuples, representing the visited positions
        :param pos: position tuple, representing the position to be checked
        :return: true or false, representing whether the position is in the visited list
        */
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        /*
        remove the connected icons on the game board
        :param pos1: position tuple(row, col) of the first icon to be removed
        :param pos2: position tuple(row, col) of the second icon to be removed
        :return: Unit
        */
        let r1 = pos1[0]
        let c1 = pos1[1]
        let r2 = pos2[0]
        let c2 = pos2[1]

        // Only remove if valid move (ensures path and same icon)
        if (this.is_valid_move(pos1, pos2)) {
            this.board[r1][c1] = " "
            this.board[r2][c2] = " "
        }
    }

    public func is_game_over(): Bool {
        /*
        Check if the game is over (i.e., if there are no more icons on the game board)
        :return: true or false ,representing whether the game is over
        */
        let rows = this.BOARD_SIZE[0]
        let cols = this.BOARD_SIZE[1]
        for (r in 0..rows) {
            for (c in 0..cols) {
                if (this.board[r][c] != " ") {
                    return false
                }
            }
        }
        return true
    }
}

class Manacher {

    /*
    This is a class that implements the Manacher algorithm to find the Longest palindromic substring in a given string.
    */

    let input_string: String

    public init(input_string: String) {
        /*
        Initializes the Manacher class with the given input_string.
        :param input_string: The input_string to be searched, String.
        */
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        /*
        Recursively calculates the length of the palindromic substring based on a given center,
        difference value, and input string (which should be a transformed string like "a|b|a").
        :param center: The center of the palindromic substring, Int64.
        :param diff: The difference between the center and the current position, Int64.
        :param string: The string to be searched, String.
        :return: The length (radius in the transformed string) of the palindromic substring, Int64.
        Example:
        For string = "a|b|a|b|a", center = 2 ('b'), the function returns 2.
        */
        let arr = string.toRuneArray()
        let n = arr.size

        if (diff <= 0) {
            return 0
        }

        let left = center - diff
        let right = center + diff

        if (left < 0 || right >= n) {
            return diff - 1
        }

        if (arr[left] == arr[right]) {
            return palindromic_length(center, diff + 1, string)
        } else {
            return diff - 1
        }
    }

    public func palindromic_string(): String {
        /*
        Finds the longest palindromic substring in the given string.
        :return: The longest palindromic substring, String.
        Example:
        For input_string = "ababaxse", returns "ababa".
        */

        // Handle empty input
        let original = this.input_string
        let origRunes = original.toRuneArray()
        if (origRunes.size == 0) {
            return ""
        }

        // Build transformed string with '|' between characters: e.g., "a|b|a|b|a"
        var transformed: String = ""
        let m = origRunes.size
        for (i in 0..m:1) {
            transformed = "${transformed}${origRunes[i]}"
            if (i + 1 < m) {
                transformed = "${transformed}|"
            }
        }

        let tRunes = transformed.toRuneArray()
        let tN = tRunes.size

        var bestStr: String = ""
        var bestLen: Int64 = 0  // length in original characters (not counting '|')

        // For each center in the transformed string, expand and track the best
        for (c in 0..tN:1) {
            let r = palindromic_length(c, 1, transformed)
            let left = c - r
            let right = c + r

            // Build candidate (skip the '|' separators) and count its length
            var cand: String = ""
            var candLen: Int64 = 0
            for (i in left..(right + 1):1) {
                if (tRunes[i] != r'|') {
                    cand = "${cand}${tRunes[i]}"
                    candLen = candLen + 1
                }
            }

            if (candLen > bestLen) {
                bestLen = candLen
                bestStr = cand
            }
        }

        // If no expansion produced a non-empty candidate (shouldn't happen for non-empty input),
        // fallback to the first character.
        if (bestLen == 0) {
            return "${origRunes[0]}"
        }

        return bestStr
    }
}

import std.collection.*

class MetricsCalculator {

    /*
    The class calculates precision, recall, F1 score, and accuracy based on predicted and true labels.
    */

    var true_positives: Int64
    var false_positives: Int64
    var false_negatives: Int64
    var true_negatives: Int64

    public init() {
        /*
        Initialize the number of all four samples to 0
        */
        this.true_positives = 0
        this.false_positives = 0
        this.false_negatives = 0
        this.true_negatives = 0
    }

    private func computeCounts(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): (Int64, Int64, Int64, Int64) {
        let n1 = predicted_labels.size
        let n2 = true_labels.size
        let n = if (n1 < n2) { n1 } else { n2 }

        var tp: Int64 = 0
        var fp: Int64 = 0
        var fn: Int64 = 0
        var tn: Int64 = 0

        for (i in 0..n) {
            let p = predicted_labels[i]
            let t = true_labels[i]
            if (p == 1 && t == 1) {
                tp = tp + 1
            } else if (p == 1 && t == 0) {
                fp = fp + 1
            } else if (p == 0 && t == 1) {
                fn = fn + 1
            } else if (p == 0 && t == 0) {
                tn = tn + 1
            }
        }

        (tp, fp, fn, tn)
    }

    public func update(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Unit {
        /*
        Update the number of all four samples(true_positives, false_positives, false_negatives, true_negatives)
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: None, change the number of corresponding samples
        >>> mc = MetricsCalculator()
        >>> mc.update(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        (this.true_positives, this.false_positives, this.false_negatives, this.true_negatives) = (1, 1, 1, 1)
        */
        let counts = this.computeCounts(predicted_labels, true_labels)
        this.true_positives = counts[0]
        this.false_positives = counts[1]
        this.false_negatives = counts[2]
        this.true_negatives = counts[3]
    }

    public func precision(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate precision
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.precision(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        let counts = this.computeCounts(predicted_labels, true_labels)
        let tp = counts[0]
        let fp = counts[1]
        let denom = tp + fp
        if (denom == 0) { 0.0 } else { Float64(tp) / Float64(denom) }
    }

    public func recall(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate recall
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.recall(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        let counts = this.computeCounts(predicted_labels, true_labels)
        let tp = counts[0]
        let fn = counts[2]
        let denom = tp + fn
        if (denom == 0) { 0.0 } else { Float64(tp) / Float64(denom) }
    }

    public func f1_score(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate f1 score, which is the harmonic mean of precision and recall
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.f1_score(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        let p = this.precision(predicted_labels, true_labels)
        let r = this.recall(predicted_labels, true_labels)
        let denom = p + r
        if (denom == 0.0) { 0.0 } else { 2.0 * p * r / denom }
    }

    public func accuracy(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        /*
        Calculate accuracy
        :param predicted_labels: ArrayList<Int64>, predicted results
        :param true_labels: ArrayList<Int64>, true labels
        :return: Float64
        >>> mc = MetricsCalculator()
        >>> mc.accuracy(ArrayList<Int64>([1, 1, 0, 0]), ArrayList<Int64>([1, 0, 0, 1]))
        0.5
        */
        let counts = this.computeCounts(predicted_labels, true_labels)
        let tp = counts[0]
        let tn = counts[3]
        let n1 = predicted_labels.size
        let n2 = true_labels.size
        let total = if (n1 < n2) { n1 } else { n2 }
        if (total == 0) { 0.0 } else { Float64(tp + tn) / Float64(total) }
    }
}

import std.collection.*

class MetricsCalculator2 {

    /*
    The class provides to calculate Mean Reciprocal Rank (MRR) and Mean Average Precision (MAP) based on input data, where MRR measures the ranking quality and MAP measures the average precision.
    */

    public init() {}

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        func rr_of(t: (ArrayList<Int64>, Int64)): Float64 {
            let arr = t[0]
            let n = arr.size
            var rr: Float64 = 0.0
            for (i in 0..n) {
                if (arr[i] == 1) {
                    rr = 1.0 / ((i + 1) as Float64)
                    break
                }
            }
            return rr
        }

        // Single tuple input
        if (data is (ArrayList<Int64>, Int64)) {
            let t = data as (ArrayList<Int64>, Int64)
            let rr = rr_of(t)
            let perList = ArrayList<Float64>([rr])
            return (rr, perList)
        }

        // List of tuples: ArrayList
        if (data is ArrayList<(ArrayList<Int64>, Int64)>) {
            let ts = data as ArrayList<(ArrayList<Int64>, Int64)>
            let m = ts.size
            var sum: Float64 = 0.0
            let perList = ArrayList<Float64>([])
            for (i in 0..m) {
                let rr = rr_of(ts[i])
                perList.add(rr, at: perList.size)
                sum = sum + rr
            }
            let avg = if (m > 0) { sum / (m as Float64) } else { 0.0 }
            return (avg, perList)
        }

        // List of tuples: Array
        if (data is Array<(ArrayList<Int64>, Int64)>) {
            let ts = data as Array<(ArrayList<Int64>, Int64)>
            let m = ts.size
            var sum: Float64 = 0.0
            let perList = ArrayList<Float64>([])
            for (i in 0..m) {
                let rr = rr_of(ts[i])
                perList.add(rr, at: perList.size)
                sum = sum + rr
            }
            let avg = if (m > 0) { sum / (m as Float64) } else { 0.0 }
            return (avg, perList)
        }

        // Fallback for unsupported input
        return (0.0, ArrayList<Float64>([]))
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        func ap_of(t: (ArrayList<Int64>, Int64)): Float64 {
            let arr = t[0]
            let gt = t[1]
            if (gt <= 0) {
                return 0.0
            }
            var hits: Int64 = 0
            var sumPrec: Float64 = 0.0
            let n = arr.size
            for (i in 0..n) {
                if (arr[i] == 1) {
                    hits = hits + 1
                    sumPrec = sumPrec + ((hits as Float64) / ((i + 1) as Float64))
                }
            }
            return sumPrec / (gt as Float64)
        }

        // Single tuple input
        if (data is (ArrayList<Int64>, Int64)) {
            let t = data as (ArrayList<Int64>, Int64)
            let ap = ap_of(t)
            let perList = ArrayList<Float64>([ap])
            return (ap, perList)
        }

        // List of tuples: ArrayList
        if (data is ArrayList<(ArrayList<Int64>, Int64)>) {
            let ts = data as ArrayList<(ArrayList<Int64>, Int64)>
            let m = ts.size
            var sum: Float64 = 0.0
            let perList = ArrayList<Float64>([])
            for (i in 0..m) {
                let ap = ap_of(ts[i])
                perList.add(ap, at: perList.size)
                sum = sum + ap
            }
            let avg = if (m > 0) { sum / (m as Float64) } else { 0.0 }
            return (avg, perList)
        }

        // List of tuples: Array
        if (data is Array<(ArrayList<Int64>, Int64)>) {
            let ts = data as Array<(ArrayList<Int64>, Int64)>
            let m = ts.size
            var sum: Float64 = 0.0
            let perList = ArrayList<Float64>([])
            for (i in 0..m) {
                let ap = ap_of(ts[i])
                perList.add(ap, at: perList.size)
                sum = sum + ap
            }
            let avg = if (m > 0) { sum / (m as Float64) } else { 0.0 }
            return (avg, perList)
        }

        // Fallback for unsupported input
        return (0.0, ArrayList<Float64>([]))
    }
}

import std.collection.*

class MinesweeperGame {

    /*
    This is a class that implements mine sweeping games including minesweeping and winning judgment.
    */

    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        /*
        Initializes the MinesweeperGame class with the size of the board and the number of mines.
        :param n: The size of the board, Int64.
        :param k: The number of mines, Int64.
        */
        this.n = n
        this.k = k
        this.minesweeper_map = MinesweeperGame.generate_mine_sweeper_map(n, k)
        this.player_map = MinesweeperGame.generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        /*
        Generates a minesweeper map with the given size of the board and the number of mines,the given parameter n is the size of the board,the size of the board is n*n,the parameter k is the number of mines,'X' represents the mine,other numbers represent the number of mines around the position.
        :return: The minesweeper map, ArrayList<ArrayList<String>>.
        */
        // Initialize all cells to "0"
        var board = ArrayList<ArrayList<String>>([])
        for (i in 0..n) {
            var row = ArrayList<String>([])
            for (j in 0..n) {
                row.add("0", at: row.size)
            }
            board.add(row, at: board.size)
        }

        // Place k mines deterministically in row-major order (0..k-1)
        var placed: Int64 = 0
        let total: Int64 = n * n
        while (placed < k && placed < total) {
            let i: Int64 = placed / n
            let j: Int64 = placed % n
            board[i][j] = "X"
            placed = placed + 1
        }

        // Compute numbers for non-mine cells
        for (i in 0..n) {
            for (j in 0..n) {
                if (board[i][j] != "X") {
                    var cnt: Int64 = 0
                    for (dx in -1..2) {
                        for (dy in -1..2) {
                            if (!(dx == 0 && dy == 0)) {
                                let ni: Int64 = i + dx
                                let nj: Int64 = j + dy
                                if (ni >= 0 && ni < n && nj >= 0 && nj < n) {
                                    if (board[ni][nj] == "X") {
                                        cnt = cnt + 1
                                    }
                                }
                            }
                        }
                    }
                    board[i][j] = "${cnt}"
                }
            }
        }
        return board
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        /*
        Generates a player map with the given size of the board, the given parameter n is the size of the board,the size of the board is n*n,'-' represents the unknown position.
        :return: The player map, ArrayList<ArrayList<String>>.
        */
        var board = ArrayList<ArrayList<String>>([])
        for (i in 0..n) {
            var row = ArrayList<String>([])
            for (j in 0..n) {
                row.add("-", at: row.size)
            }
            board.add(row, at: board.size)
        }
        return board
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        /*
        Checks whether the player has won the game. If all non-mine cells in minesweeper_map
        have been revealed in the given map (i.e., not '-'), return true; otherwise false.
        */
        for (i in 0..this.n) {
            for (j in 0..this.n) {
                if (this.minesweeper_map[i][j] != "X" && map[i][j] == "-") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        /*
        Sweeps the given position.
        :param x: The x coordinate of the position, Int64.
        :param y: The y coordinate of the position, Int64.
        :return:
            - false if a mine is hit.
            - true if, after revealing, all non-mine cells are revealed (win).
            - otherwise, the current player_map (ArrayList<ArrayList<String>>).
        */
        // Bounds check
        if (x < 0 || y < 0 || x >= this.n || y >= this.n) {
            return this.player_map
        }

        let cell = this.minesweeper_map[x][y]

        // If mine is clicked, game lost
        if (cell == "X") {
            // Optionally reveal the mine
            this.player_map[x][y] = "X"
            return false
        }

        // If already revealed, just evaluate win condition
        if (this.player_map[x][y] != "-") {
            if (this.check_won(this.player_map)) {
                return true
            } else {
                return this.player_map
            }
        }

        // Reveal logic: if "0", flood fill zeros and boundary numbers; else reveal the number
        if (cell == "0") {
            var queue = ArrayList<(Int64, Int64)>([])
            queue.add((x, y), at: queue.size)

            while (queue.size > 0) {
                let p = queue[0]
                queue.remove(at: 0)

                let cx: Int64 = p[0]
                let cy: Int64 = p[1]

                if (this.player_map[cx][cy] != "-") {
                    continue
                }

                let v = this.minesweeper_map[cx][cy]
                this.player_map[cx][cy] = v

                if (v == "0") {
                    for (dx in -1..2) {
                        for (dy in -1..2) {
                            if (!(dx == 0 && dy == 0)) {
                                let nx: Int64 = cx + dx
                                let ny: Int64 = cy + dy
                                if (nx >= 0 && nx < this.n && ny >= 0 && ny < this.n) {
                                    if (this.minesweeper_map[nx][ny] != "X" && this.player_map[nx][ny] == "-") {
                                        // Reveal boundary number immediately; enqueue zeros
                                        let nv = this.minesweeper_map[nx][ny]
                                        this.player_map[nx][ny] = nv
                                        if (nv == "0") {
                                            queue.add((nx, ny), at: queue.size)
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        } else {
            this.player_map[x][y] = cell
        }

        if (this.check_won(this.player_map)) {
            return true
        } else {
            return this.player_map
        }
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.time.DateTime
import std.math.abs

class MovieBookingSystem {

    /*
    this is a class as movie booking system, which allows to add movies, book tickets and check the available movies within a given time range. 
    */

    let movies: ArrayList<HashMap<String, Any>>

    public init() {
        /*
        Initialize movies contains the information about movies
        >>> system.movies
        [{'name': 'Batman', 'price': 49.9, 'start_time': DateTime.parse("2023/01/01 17:05", "yyyy/MM/dd HH:mm"), 'end_time': DateTime.parse("2023/01/01 19:25", "yyyy/MM/dd HH:mm"),
        'seats': ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0, 0]),
            ArrayList<Int64>([0, 0, 0]),
            ArrayList<Int64>([0, 0, 0])
            ])}]
        */
        movies = ArrayList<HashMap<String, Any>>()
    }

    public func add_movie(name: String, price: Float64, start_time: String, end_time: String, n: Int64): Unit {
        /*
        Add a new movie into this.movies
        :param name: String, movie name
        :param price: Float64, price for one ticket
        :param start_time: String
        :param end_time: String
        :param n: Int64, the size of seats(n*n)
        >>> system.add_movie('Batman', 49.9, '2023/01/01 17:05', '2023/01/01 19:25', 3)
        >>> system.movies
        [{'name': 'Batman', 'price': 49.9, 'start_time': DateTime.parse("2023/01/01 17:05", "yyyy/MM/dd HH:mm"), 'end_time': DateTime.parse("2023/01/01 19:25", "yyyy/MM/dd HH:mm"),
        'seats': ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0, 0]),
            ArrayList<Int64>([0, 0, 0]),
            ArrayList<Int64>([0, 0, 0])
            ])}]
        */
        // build n x n seats with 0
        let seats: ArrayList<ArrayList<Int64>> = ArrayList<ArrayList<Int64>>()
        for (i in 0..n) {
            let row: ArrayList<Int64> = ArrayList<Int64>()
            for (j in 0..n) {
                row.add(0, at: row.size)
            }
            seats.add(row, at: seats.size)
        }

        let st = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let et = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")

        let movie = HashMap<String, Any>([
            ("name", name),
            ("price", price),
            ("start_time", st),
            ("end_time", et),
            ("seats", seats)
        ])
        movies.add(movie, at: movies.size)
    }

    public func book_ticket(name: String, seats_to_book: ArrayList<ArrayList<Int64>>): String {
        /*
        Book tickets for a movie. Change the seats value in this.movies if book successfully.
        :param name: String, movie name
        :param seats_to_book: ArrayList<ArrayList<Int64>>, representing seats to book [[row1, col1], [row2, col2], ...]
        :return: String, booking status message. "Movie not found." for no such movie.
                "Booking success." for successfully booking, or "Booking failed." otherwise
        >>> system.add_movie('Batman', 49.9, '2023/01/01 17:05', '2023/01/01 19:25', 3)
        >>> system.book_ticket('Batman', ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0]), ArrayList<Int64>([0, 1])]))
        'Booking success.'
        >>> system.book_ticket('Batman', ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0])]))
        'Booking failed.'
        >>> system.book_ticket('batman', ArrayList<ArrayList<Int64>>([ArrayList<Int64>([0, 0])]))
        'Movie not found.'
        */
        var idx: Int64 = -1
        for (i in 0..movies.size) {
            let mv = movies[i]
            let mvName = mv["name"] as String
            if (mvName == name) {
                idx = i
                break
            }
        }
        if (idx == -1) {
            return "Movie not found."
        }

        let movie = movies[idx]
        let seats: ArrayList<ArrayList<Int64>> = movie["seats"] as ArrayList<ArrayList<Int64>>
        let nRows = seats.size
        let nCols = if (nRows > 0) { seats[0].size } else { 0 }

        // validate all seats first
        for (k in 0..seats_to_book.size) {
            let pos = seats_to_book[k]
            if (pos.size < 2) {
                return "Booking failed."
            }
            let r = pos[0]
            let c = pos[1]
            if (r < 0 || c < 0) {
                return "Booking failed."
            }
            if (r >= nRows || c >= nCols) {
                return "Booking failed."
            }
            let rowList = seats[r]
            if (rowList[c] != 0) {
                return "Booking failed."
            }
        }

        // perform booking
        for (k in 0..seats_to_book.size) {
            let pos = seats_to_book[k]
            let r = pos[0]
            let c = pos[1]
            let rowList = seats[r]
            rowList[c] = 1
        }
        // reflect back (optional, in case map requires overwrite)
        movie.add("seats", seats)
        return "Booking success."
    }

    public func available_movies(start_time: String, end_time: String): ArrayList<String> {
        /*
        Get a list of available movies within the specified time range
        :param start_time: String, start time in yyyy/MM/dd HH:mm format
        :param end_time: String, end time in yyyy/MM/dd HH:mm format
        :return: ArrayList<String>, names of available movies
        >>> system.add_movie('Batman', 49.9, '2023/01/01 17:05', '2023/01/01 19:25', 3)
        >>> system.available_movies('2023/01/01 12:00', '2023/01/01 22:00')
        ['Batman']
        */
        let res = ArrayList<String>()
        let st = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let et = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")

        for (i in 0..movies.size) {
            let mv = movies[i]
            let mvName = mv["name"] as String
            let mvStart = mv["start_time"] as DateTime
            let mvEnd = mv["end_time"] as DateTime
            if (mvStart >= st && mvEnd <= et) {
                res.add(mvName, at: res.size)
            }
        }
        return res
    }
}

import std.random.Random
import std.collection.*

class MusicPlayer {

    /*
    This is a class as a music player that provides to play, stop, add songs, remove songs, set volume, shuffle, and switch to the next or previous song.
    */

    var playlist: ArrayList<String>
    var current_song: Option<String>
    var volume: Int64

    public init() {
        /*
        Initializes the music player with an empty playlist, no current song, and a default volume of 50.
        */
        this.playlist = ArrayList<String>()
        this.current_song = None<String>
        this.volume = 50
    }

    private func index_of(song: String): Option<Int64> {
        for (i in 0..this.playlist.size) {
            if (this.playlist[i] == song) {
                return Some<Int64>(i)
            }
        }
        return None<Int64>
    }

    public func add_song(song: String): Unit {
        /*
        Adds a song to the playlist.
        :param song: The song to add to the playlist, String.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.add_song("song1")
        >>> musicPlayer.playlist
        ['song1']
        */
        this.playlist.add(song, at: this.playlist.size)
    }

    public func remove_song(song: String): Unit {
        /*
        Removes a song from the playlist.
        :param song: The song to remove from the playlist, String.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.remove_song("song1")
        >>> musicPlayer.playlist
        ['song2']
        */
        let idx_opt = this.index_of(song)
        match (idx_opt) {
            case Some<Int64>(i) => {
                this.playlist.remove(at: i)
            }
            case None<Int64> => {
                // do nothing
            }
        }
    }

    public func play(): Option<String> {
        /*
        Plays the current song in the playlist.
        :return: The current song in the playlist, or None if the playlist is empty, Option<String>.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = Some<String>("song1")
        >>> musicPlayer.play()
        'song1'
        */
        if (this.playlist.size == 0) {
            return None<String>
        }
        match (this.current_song) {
            case Some<String>(s) => {
                // Ensure the current song exists in the playlist
                let idx = this.index_of(s)
                match (idx) {
                    case Some<Int64>(_) => { return Some<String>(s) }
                    case None<Int64> => {
                        // Fallback to first song if current is not in playlist
                        let first = this.playlist[0]
                        this.current_song = Some<String>(first)
                        return this.current_song
                    }
                }
            }
            case None<String> => {
                let first = this.playlist[0]
                this.current_song = Some<String>(first)
                return this.current_song
            }
        }
    }

    public func stop(): Bool {
        /*
        Stops the current song in the playlist.
        :return: true if the current song was stopped, false if there was no current song.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = Some<String>("song1")
        >>> musicPlayer.stop()
        true
        */
        match (this.current_song) {
            case Some<String>(_ ) => {
                this.current_song = None<String>
                return true
            }
            case None<String> => {
                return false
            }
        }
    }

    public func switch_song(): Bool {
        /*
        Switches to the next song in the playlist.
        :return: true if the next song was switched to, false if there was no next song.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = Some<String>("song1")
        >>> musicPlayer.switch_song()
        true
        */
        if (this.playlist.size == 0) {
            return false
        }
        match (this.current_song) {
            case Some<String>(s) => {
                let idx_opt = this.index_of(s)
                match (idx_opt) {
                    case Some<Int64>(i) => {
                        if (i + 1 < this.playlist.size) {
                            this.current_song = Some<String>(this.playlist[i + 1])
                            return true
                        } else {
                            return false
                        }
                    }
                    case None<Int64> => { return false }
                }
            }
            case None<String> => { return false }
        }
    }

    public func previous_song(): Bool {
        /*
        Switches to the previous song in the playlist.
        :return: true if the previous song was switched to, false if there was no previous song.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = Some<String>("song2")
        >>> musicPlayer.previous_song()
        true
        */
        if (this.playlist.size == 0) {
            return false
        }
        match (this.current_song) {
            case Some<String>(s) => {
                let idx_opt = this.index_of(s)
                match (idx_opt) {
                    case Some<Int64>(i) => {
                        if (i > 0) {
                            this.current_song = Some<String>(this.playlist[i - 1])
                            return true
                        } else {
                            return false
                        }
                    }
                    case None<Int64> => { return false }
                }
            }
            case None<String> => { return false }
        }
    }

    public func set_volume(volume: Int64): Bool {
        /*
        Sets the volume of the music player, if the volume is between 0 and 100 inclusive it is valid.
        :param volume: The volume to set the music player to, Int64.
        :return: true if the volume was set, false if the volume was invalid.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.set_volume(50)
        true
        >>> musicPlayer.volume
        50
        */
        if (volume < 0 || volume > 100) {
            return false
        }
        this.volume = volume
        return true
    }

    public func shuffle(): Bool {
        /*
        Shuffles the playlist.
        :return: true if the playlist was shuffled, false if the playlist is empty.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.shuffle()
        true
        */
        if (this.playlist.size == 0) {
            return false
        }
        let rnd = Random()
        // Fisher-Yates shuffle
        for (i in 0..this.playlist.size) {
            // pick j in [i, size)
            // Assuming Random.nextInt(min, max) inclusive bounds are supported
            let j = rnd.nextInt(i, this.playlist.size - 1)
            if (j != i) {
                let temp = this.playlist[i]
                this.playlist[i] = this.playlist[j]
                this.playlist[j] = temp
            }
        }
        return true
    }
}

import std.collection.*

class NLPDataProcessor {

    /*
    The class processes NLP data by removing stop words from a list of strings using a pre-defined stop word list.
    */

    public func construct_stop_word_list(): ArrayList<String> {
        /*
        Construct a stop word list including 'a', 'an', 'the'.
        :return: a list of stop words
        >>> nlp_data_processor = NLPDataProcessor()
        >>> nlp_data_processor.construct_stop_word_list()
        ['a', 'an', 'the']
        */
        return ArrayList<String>(["a", "an", "the"])
    }

    public func remove_stop_words(string_list: ArrayList<String>, stop_word_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        Remove all the stop words from the list of strings.
        :param string_list: a list of strings
        :param stop_word_list: a list of stop words
        :return: a list of words without stop words
        >>> nlp_data_processor = NLPDataProcessor()
        >>> nlp_data_processor.process(ArrayList<String>(['This is a test.']), ArrayList<String>(['a', 'an', 'the']))
        [['This', 'is', 'test.']]
        */
        let result = ArrayList<ArrayList<String>>([])
        for (i in 0..string_list.size) {
            let s = string_list[i]
            let tokens = this.split_by_space(s)
            var filtered = ArrayList<String>([])
            for (j in 0..tokens.size) {
                let token = tokens[j]
                if (!this.contains_string(stop_word_list, token)) {
                    filtered.add(token, at: filtered.size)
                }
            }
            result.add(filtered, at: result.size)
        }
        return result
    }

    public func process(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        Construct a stop word list including 'a', 'an', 'the', and remove all the stop words from the list of strings.
        :param string_list: a list of strings
        :return: a list of words without stop words
        >>> nlp_data_processor = NLPDataProcessor()
        >>> NLPDataProcessor.process(ArrayList<String>(['This is a test.']))
        [['This', 'is', 'test.']]
        */
        let stop_words = this.construct_stop_word_list()
        return this.remove_stop_words(string_list, stop_words)
    }

    private func contains_string(list: ArrayList<String>, value: String): Bool {
        for (i in 0..list.size) {
            if (list[i] == value) {
                return true
            }
        }
        return false
    }

    private func split_by_space(s: String): ArrayList<String> {
        var tokens = ArrayList<String>([])
        var token: String = ""
        let runes = s.toRuneArray()
        for (i in 0..runes.size) {
            let ch: Rune = runes[i]
            if (ch == r' ') {
                if (token != "") {
                    tokens.add(token, at: tokens.size)
                    token = ""
                }
            } else {
                token = "${token}${ch}"
            }
        }
        if (token != "") {
            tokens.add(token, at: tokens.size)
        }
        return tokens
    }
}

import std.collection.*
import std.regex.*
import std.sort.*
import std.unicode.*

class NLPDataProcessor2 {

    /*
    The class processes NLP data by extracting words from a list of strings, calculating the frequency of each word, and returning the top 5 most frequent words.
    */

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        /*
        keep only English letters and spaces in the string, then convert the string to lower case, and then split the string into a list of words.
        :param string_list: a list of strings
        :return: words_list: a list of words lists
        >>> NLPDataProcessor.process_data(ArrayList<String>(['This is a test.']))
        [['this', 'is', 'a', 'test']]
        */
        let nonLetter = Regex("[^A-Za-z ]+")
        let whitespace = Regex("\\s+")
        var words_list = ArrayList<ArrayList<String>>([])

        for (i in 0..string_list.size) {
            let s = string_list[i]
            let cleaned = nonLetter.replaceAll(s, " ")
            let lower = cleaned.toLowerCase()
            let parts = lower.split(whitespace)  // split on one or more whitespaces

            // Filter out empty strings
            var filtered = ArrayList<String>([])
            for (j in 0..parts.size) {
                let w = parts[j]
                if (w != "") {
                    filtered.add(w, at: filtered.size)
                }
            }

            words_list.add(filtered, at: words_list.size)
        }

        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        /*
        Calculate the word frequency of each word in the list of words list, and sort the word frequency dictionary by value in descending order.
        :param words_list: a list of words lists
        :return: top 5 word frequency dictionary, a dictionary of word frequency, key is word, value is frequency
        >>> NLPDataProcessor.calculate_word_frequency(ArrayList<ArrayList<String>>([ArrayList<String>(['this', 'is', 'a', 'test']), ArrayList<String>(['this', 'is', 'another', 'test'])]))
        {'this': 2, 'is': 2, 'test': 2, 'a': 1, 'another': 1}
        */
        var freq = HashMap<String, Int64>([])
        var keys = ArrayList<String>([])

        // Count frequencies and track unique words
        for (i in 0..words_list.size) {
            let lst = words_list[i]
            for (j in 0..lst.size) {
                let word = lst[j]
                let oldCount = freq.get(word) ?? 0
                if (oldCount == 0) {
                    keys.add(word, at: keys.size)
                }
                freq.add(word, oldCount + 1)
            }
        }

        // Sort unique words by frequency (descending)
        let lessThan = { l: String, r: String => freq[l] < freq[r] }
        sort(keys, lessThan: lessThan, descending: true)

        // Take top 5
        let limit = if (keys.size < 5) { keys.size } else { 5 }

        var top = HashMap<String, Int64>([])
        for (k in 0..limit) {
            let w = keys[k]
            top.add(w, freq[w])
        }

        return top
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        /*
        keep only English letters and spaces in the string, then convert the string to lower case, and then split the string into a list of words. Calculate the word frequency of each word in the list of words list, and sort the word frequency dictionary by value in descending order.
        :param string_list: a list of strings
        :return: top 5 word frequency dictionary, a dictionary of word frequency, key is word, value is frequency
        >>> NLPDataProcessor.process(ArrayList<String>(['This is a test.', 'This is another test.']))
        {'this': 2, 'is': 2, 'test': 2, 'a': 1, 'another': 1}
        */
        let words_list = this.process_data(string_list)
        return this.calculate_word_frequency(words_list)
    }
}

class NumberConverter {

    public static func decimal_to_binary(decimal_num: Int64): String {
        return NumberConverter.decimalToBase(decimal_num, 2)
    }

    public static func binary_to_decimal(binary_num: String): Int64 {
        return NumberConverter.baseToDecimal(binary_num, 2)
    }

    public static func decimal_to_octal(decimal_num: Int64): String {
        return NumberConverter.decimalToBase(decimal_num, 8)
    }

    public static func octal_to_decimal(octal_num: String): Int64 {
        return NumberConverter.baseToDecimal(octal_num, 8)
    }

    public static func decimal_to_hex(decimal_num: Int64): String {
        return NumberConverter.decimalToBase(decimal_num, 16)
    }

    public static func hex_to_decimal(hex_num: String): Int64 {
        return NumberConverter.baseToDecimal(hex_num, 16)
    }

    // Helpers

    private static func decimalToBase(n: Int64, base: Int64): String {
        if (base < 2 || base > 16) {
            return ""
        }
        if (n == 0) {
            return "0"
        }
        var value = n
        var sign = ""
        if (value < 0) {
            sign = "-"
            value = -value
        }
        var res = ""
        while (value > 0) {
            let rem = value % base
            let d = NumberConverter.digitToString(rem)
            res = "${d}${res}"
            value = value / base
        }
        return "${sign}${res}"
    }

    private static func baseToDecimal(s: String, base: Int64): Int64 {
        let runes = s.toRuneArray()
        if (runes.size == 0) {
            return 0
        }
        var sign: Int64 = 1
        var startIdx = 0
        if (runes[0] == r'-') {
            sign = -1
            startIdx = 1
        }
        var acc: Int64 = 0
        let n = runes.size
        for (i in startIdx..n) {
            let d = NumberConverter.runeToDigit(runes[i])
            if (d < 0 || d >= base) {
                // Invalid digit for the base; return 0 conservatively
                return 0
            }
            acc = acc * base + d
        }
        return sign * acc
    }

    private static func digitToString(d: Int64): String {
        return match (d) {
            case 0 => "0"
            case 1 => "1"
            case 2 => "2"
            case 3 => "3"
            case 4 => "4"
            case 5 => "5"
            case 6 => "6"
            case 7 => "7"
            case 8 => "8"
            case 9 => "9"
            case 10 => "a"
            case 11 => "b"
            case 12 => "c"
            case 13 => "d"
            case 14 => "e"
            case 15 => "f"
            case _ => ""
        }
    }

    private static func runeToDigit(r: Rune): Int64 {
        return match (r) {
            case r'0' => 0
            case r'1' => 1
            case r'2' => 2
            case r'3' => 3
            case r'4' => 4
            case r'5' => 5
            case r'6' => 6
            case r'7' => 7
            case r'8' => 8
            case r'9' => 9
            case r'a' => 10
            case r'b' => 11
            case r'c' => 12
            case r'd' => 13
            case r'e' => 14
            case r'f' => 15
            case r'A' => 10
            case r'B' => 11
            case r'C' => 12
            case r'D' => 13
            case r'E' => 14
            case r'F' => 15
            case _ => -1
        }
    }
}

import std.convert.Parsable
import std.unicode.UnicodeStringExtension

class NumberWordFormatter {

    /*
    This is a class that provides to convert numbers into their corresponding English word representation, including handling the conversion of both the integer and decimal parts, and incorporating appropriate connectors and units.
    */

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        /*
        Initialize NumberWordFormatter object.
        */
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        /*
        Converts a number into words format
        :param x: Option<String>, the number to be converted into words format
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        let s = x ?? ""
        return this.format_string(s)
    }

    public func format_string(x: String): String {
        /*
        Converts a string representation of a number into words format
        :param x: String, the string representation of a number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format_string("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        */
        let runes = x.toRuneArray()
        let n = runes.size

        // Find decimal point position (if any)
        var dotIndex: Int64 = -1
        var i: Int64 = 0
        while (i < n) {
            if (runes[i] == r'.') {
                dotIndex = i
                break
            }
            i = i + 1
        }

        let intEnd: Int64 = if (dotIndex >= 0) { dotIndex } else { n }
        // Remove leading zeros in integer part by advancing intStart
        var intStart: Int64 = 0
        while (intStart < intEnd && this.digitVal(runes[intStart]) == 0) {
            intStart = intStart + 1
        }

        // Build integer words by grouping into triplets from right to left
        var res: String = ""
        if (intStart >= intEnd) {
            // integer part is zero
            res = "ZERO"
        } else {
            var groupIdx: Int64 = 0
            var right: Int64 = intEnd
            while (right > intStart) {
                // triplet: [max(intStart, right-3), right)
                var left: Int64 = right - 3
                if (left < intStart) {
                    left = intStart
                }
                let segVal = this.parseIntRange(runes, left, right)
                if (segVal != 0) {
                    let segWords = this.words_three(segVal)
                    let suffix = this.parse_more(groupIdx)
                    var block: String = segWords
                    if (suffix != "") {
                        block = block + " " + suffix
                    }
                    if (res == "") {
                        res = block
                    } else {
                        res = block + " " + res
                    }
                }
                right = left
                groupIdx = groupIdx + 1
            }
            if (res == "") {
                res = "ZERO"
            }
        }

        // Decimal part (if any): read each digit after '.'
        if (dotIndex >= 0 && dotIndex + 1 < n) {
            var j: Int64 = dotIndex + 1
            var firstFracFound: Bool = false
            var fracWords: String = ""
            while (j < n) {
                let d = this.digitVal(runes[j])
                // Ignore non-digits defensively
                if (d >= 0) {
                    let word = if (d == 0) { "ZERO" } else { this.NUMBER[d] }
                    if (!firstFracFound) {
                        fracWords = word
                        firstFracFound = true
                    } else {
                        fracWords = fracWords + " " + word
                    }
                }
                j = j + 1
            }
            if (fracWords != "") {
                res = res + " POINT " + fracWords
            }
        }

        return res + " ONLY"
    }

    public func trans_two(s: String): String {
        /*
        Converts a two-digit number into words format
        :param s: String, the two-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_two("23")
        "TWENTY THREE"
        */
        let val = this.parseIntString(s)
        return this.words_two(val)
    }

    public func trans_three(s: String): String {
        /*
        Converts a three-digit number into words format
        :param s: String, the three-digit number
        :return: String, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_three("123")
        "ONE HUNDRED AND TWENTY THREE"
        */
        let val = this.parseIntString(s)
        return this.words_three(val)
    }

    public func parse_more(i: Int64): String {
        /*
        Parses the thousand/million/billion suffix based on the index
        :param i: Int64, the index representing the magnitude (thousand, million, billion)
        :return: String, the corresponding suffix for the magnitude
        >>> formatter = NumberWordFormatter()
        >>> formatter.parse_more(1)
        "THOUSAND"
        */
        if (i >= 0 && i < this.NUMBER_MORE.size) {
            return this.NUMBER_MORE[i]
        } else {
            return ""
        }
    }

    // ===== Helper functions =====

    func digitVal(r: Rune): Int64 {
        // Returns -1 for non-digits
        return match (r) {
            case r'0' => 0
            case r'1' => 1
            case r'2' => 2
            case r'3' => 3
            case r'4' => 4
            case r'5' => 5
            case r'6' => 6
            case r'7' => 7
            case r'8' => 8
            case r'9' => 9
            case _ => -1
        }
    }

    func parseIntRange(runes: Array<Rune>, start: Int64, end: Int64): Int64 {
        // parse integer value of digits in [start, end)
        var v: Int64 = 0
        var i: Int64 = start
        while (i < end) {
            let d = this.digitVal(runes[i])
            if (d < 0) {
                // ignore non-digits
                i = i + 1
                continue
            }
            v = v * 10 + d
            i = i + 1
        }
        return v
    }

    func parseIntString(s: String): Int64 {
        let arr = s.toRuneArray()
        return this.parseIntRange(arr, 0, arr.size)
    }

    func words_two(n: Int64): String {
        if (n <= 0) {
            return ""
        }
        if (n < 10) {
            return this.NUMBER[n]
        }
        if (n < 20) {
            return this.NUMBER_TEEN[n - 10]
        }
        let tens = n / 10
        let ones = n % 10
        var res = this.NUMBER_TEN[tens - 1]
        if (ones > 0) {
            res = res + " " + this.NUMBER[ones]
        }
        return res
    }

    func words_three(n: Int64): String {
        if (n <= 0) {
            return ""
        }
        let hundreds = n / 100
        let rem = n % 100
        if (hundreds == 0) {
            return this.words_two(rem)
        }
        var res = this.NUMBER[hundreds] + " HUNDRED"
        if (rem > 0) {
            res = res + " AND " + this.words_two(rem)
        }
        return res
    }
}

class NumericEntityUnescaper {

    public init() {}

    public func replace(string: String): String {
        let runes = string.toRuneArray()
        let n = runes.size
        var i: Int64 = 0
        var out: String = ""

        while (i < n) {
            if (runes[i] == r'&' && i + 1 < n && runes[i + 1] == r'#') {
                var j: Int64 = i + 2
                var is_hex: Bool = false
                if (j < n && (runes[j] == r'x' || runes[j] == r'X')) {
                    is_hex = true
                    j = j + 1
                }

                var value: Int64 = 0
                var consumed: Int64 = 0
                if (is_hex) {
                    while (j < n) {
                        let dv = NumericEntityUnescaper.hex_digit_value(runes[j])
                        if (dv < 0) {
                            break
                        }
                        value = value * 16 + dv
                        j = j + 1
                        consumed = consumed + 1
                    }
                } else {
                    while (j < n) {
                        let dv = NumericEntityUnescaper.dec_digit_value(runes[j])
                        if (dv < 0) {
                            break
                        }
                        value = value * 10 + dv
                        j = j + 1
                        consumed = consumed + 1
                    }
                }

                if (consumed == 0) {
                    // Not a valid numeric entity; emit '&' and continue.
                    out = out + "${runes[i]}"
                    i = i + 1
                    continue
                }

                // Optional semicolon
                if (j < n && runes[j] == r';') {
                    j = j + 1
                }

                // Convert codepoint to Rune and append.
                let ch: Rune = value as Rune
                out = out + "${ch}"
                i = j
                continue
            }

            // Normal character passthrough
            out = out + "${runes[i]}"
            i = i + 1
        }

        return out
    }

    public static func is_hex_char(char: Rune): Bool {
        return NumericEntityUnescaper.is_digit(char)
            || (char >= r'a' && char <= r'f')
            || (char >= r'A' && char <= r'F')
    }

    private static func is_digit(char: Rune): Bool {
        return (char >= r'0' && char <= r'9')
    }

    private static func dec_digit_value(char: Rune): Int64 {
        if (char == r'0') { return 0 }
        if (char == r'1') { return 1 }
        if (char == r'2') { return 2 }
        if (char == r'3') { return 3 }
        if (char == r'4') { return 4 }
        if (char == r'5') { return 5 }
        if (char == r'6') { return 6 }
        if (char == r'7') { return 7 }
        if (char == r'8') { return 8 }
        if (char == r'9') { return 9 }
        return -1
    }

    private static func hex_digit_value(char: Rune): Int64 {
        // 0-9
        let dv_dec = NumericEntityUnescaper.dec_digit_value(char)
        if (dv_dec >= 0) {
            return dv_dec
        }
        // a-f
        if (char == r'a') { return 10 }
        if (char == r'b') { return 11 }
        if (char == r'c') { return 12 }
        if (char == r'd') { return 13 }
        if (char == r'e') { return 14 }
        if (char == r'f') { return 15 }
        // A-F
        if (char == r'A') { return 10 }
        if (char == r'B') { return 11 }
        if (char == r'C') { return 12 }
        if (char == r'D') { return 13 }
        if (char == r'E') { return 14 }
        if (char == r'F') { return 15 }
        return -1
    }
}

import std.collection.*

interface Equatable<T> {
    operator func ==(that: T): Bool
    operator func !=(that: T): Bool
}

class Dish <: Equatable<Dish> {

    let dish: String
    let price: Int64
    var count: Int64

    public init(dish: String, price: Int64, count: Int64) {
        this.dish = dish
        this.price = price
        this.count = count
    }

    public override operator func != (that: Dish): Bool {
        return this.dish != that.dish || this.price != that.price || this.count != that.count
    }

    public override operator func == (that: Dish): Bool {
        return this.dish == that.dish && this.price == that.price && this.count == that.count
    }
}

class Order {
    /*
    The class manages restaurant orders by allowing the addition of dishes, calculation of the total cost, and checkout.
    */

    let menu: ArrayList<Dish>
    let selected_dishes: ArrayList<Dish>
    let sales: HashMap<String, Float64>

    public init() {
        /*
        Initialize the order management system
        this.menu stores the dishes of resturant inventory
        menu = [Dish("dish name", price, count), ...]
        this.selected_dishes stores the dished selected by customer
        selected_dish = Dish("dish name", price, count)
        this.sales stores the sales of each dish
        sales = {dish name: sales}
        */
        this.menu = ArrayList<Dish>()
        this.selected_dishes = ArrayList<Dish>()
        this.sales = HashMap<String, Float64>()
    }

    public func add_dish(dish: Dish): Bool {
        /*
        Check the this.menu and add into this.selected_dish if the dish count is valid.
        And if the dish has successfully been added, change the count in this.menu.
        :param dish: Dish, the information of dish.
        :return: true if successfully added, or false otherwise.
        */
        if (dish.count <= 0) {
            return false
        }

        var idx: Int64 = -1
        for (i in 0..this.menu.size) {
            let m = this.menu[i]
            if (m.dish == dish.dish && m.price == dish.price) {
                if (m.count >= dish.count) {
                    idx = i
                }
                break
            }
        }

        if (idx < 0) {
            return false
        }

        // Add to selected_dishes (accumulate if already selected)
        var updated = false
        for (i in 0..this.selected_dishes.size) {
            let s = this.selected_dishes[i]
            if (s.dish == dish.dish && s.price == dish.price) {
                s.count = s.count + dish.count
                updated = true
                break
            }
        }
        if (!updated) {
            let copy = Dish(dish.dish, dish.price, dish.count)
            this.selected_dishes.add(copy, at: this.selected_dishes.size)
        }

        // Decrease stock in menu
        let m = this.menu[idx]
        m.count = m.count - dish.count

        return true
    }

    public func calculate_total(): Float64 {
        /*
        Calculate the total price of dishes that have been ordered. Multiply the count, price and sales.
        :return total: Float64, the final total price.
        */
        var total = 0.0
        for (i in 0..this.selected_dishes.size) {
            let d = this.selected_dishes[i]
            let sale = this.sales.get(d.dish) ?? 1.0
            let base = d.price * d.count
            total = total + base * sale
        }
        return total
    }

    public func checkout(): Option<Float64> {
        /*
        Check out the dished ordered. IF the this.selected_dishes is not empty, invoke the calculate_total
        method to check out.
        :return None if the this.selected_dishes is empty, or total(return value of calculate_total) otherwise.
        */
        if (this.selected_dishes.size == 0) {
            return None<Float64>
        }
        let total = this.calculate_total()
        return Some<Float64>(total)
    }
}

