class Server {

    /*
    This is a class as a server, which handles a white list, message sending and receiving, and information display.
    */

    let white_list: ArrayList<Int64>
    let send_struct: HashMap<String, Any>
    let receive_struct: HashMap<String, Any>

    public init() {
        /*
        Initialize the whitelist as an empty list, and initialize the sending and receiving information as an empty map.
        */
        this.white_list = ArrayList<Int64>()
        this.send_struct = HashMap<String, Any>()
        this.receive_struct = HashMap<String, Any>()
    }

    private func indexOfWhitelist(addr: Int64): Option<Int64> {
        for (i in 0..this.white_list.size) {
            if (this.white_list[i] == addr) {
                return Some<Int64>(i)
            }
        }
        return None<Int64>
    }

    private func is_valid_info(info: HashMap<String, Any>): Bool {
        let addr_opt = info.get("addr")
        let content_opt = info.get("content")

        let addr_ok = match (addr_opt) {
            case Some<Any>(a) => a is Int64
            case _ => false
        }
        let content_ok = match (content_opt) {
            case Some<Any>(c) => c is String
            case _ => false
        }
        return addr_ok && content_ok
    }

    public func add_white_list(addr: Int64): Option<ArrayList<Int64>> {
        /*
        Add an address to the whitelist and do nothing if it already exists
        :param addr: Int64, address to be added
        :return: new whitelist, return None if the address already exists
        >>> server = Server()
        >>> server.add_white_list(88)
        [88]
        */
        let exists = match (this.indexOfWhitelist(addr)) {
            case Some<Int64>(_) => true
            case _ => false
        }
        if (exists) {
            return None<ArrayList<Int64>>
        } else {
            this.white_list.add(addr, at: this.white_list.size)
            return Some<ArrayList<Int64>>(this.white_list)
        }
    }

    public func del_white_list(addr: Int64): Option<ArrayList<Int64>> {
        /*
        Remove an address from the whitelist and do nothing if it does not exist
        :param addr: Int64, address to be deleted
        :return: new whitelist, return None if the address does not exist
        >>> server.add_white_list(88)
        >>> server.del_white_list(88)
        []
        */
        match (this.indexOfWhitelist(addr)) {
            case Some<Int64>(i) => {
                this.white_list.remove(at: i)
                return Some<ArrayList<Int64>>(this.white_list)
            }
            case _ => {
                return None<ArrayList<Int64>>
            }
        }
    }

    public func recv(info: HashMap<String, Any>): Any {
        /*
        Receive information containing address and content. If the address is on the whitelist, receive the content; otherwise, do not receive it
        :param info: HashMap<String, Any>, information dictionary containing address and content
        :return: if successfully received, return the content of the information; otherwise, return false
        >>> server.recv(HashMap<String, Any>([("addr",88),("content","abc")]))
        abc
        */
        if (!this.is_valid_info(info)) {
            return false
        }

        let addr_val: Int64 = match (info.get("addr")) {
            case Some<Any>(a) => a as Int64
            case _ => -1
        }
        let content_val: String = match (info.get("content")) {
            case Some<Any>(c) => c as String
            case _ => ""
        }

        let in_whitelist = match (this.indexOfWhitelist(addr_val)) {
            case Some<Int64>(_) => true
            case _ => false
        }

        if (in_whitelist) {
            this.receive_struct = info
            return content_val
        } else {
            return false
        }
    }

    public func send(info: HashMap<String, Any>): Option<String> {
        /*
        Send information containing address and content
        :param info: HashMap<String, Any>, information dictionary containing address and content
        :return: if successfully sent, return None; otherwise, return "info structure is not correct"
        >>> server.send(HashMap<String, Any>([("addr",66),("content","ABC")]))
        None
        this.send_struct = HashMap<String, Any>([("addr",66),("content","ABC")])
        */
        if (!this.is_valid_info(info)) {
            return Some<String>("info structure is not correct")
        }
        this.send_struct = info
        return None<String>
    }

    public func show(type_struct: String): Option<HashMap<String, Any>> {
        /*
        Returns struct of the specified type
        :param type: String, the type of struct to be returned, which can be 'send' or 'receive'
        :return: if type is equal to 'send' or 'receive', return the corresponding struct; otherwise, return None
        >>> server.recv(HashMap<String, Any>([("addr",88),("content","abc")]))
        >>> server.send(HashMap<String, Any>([("addr",66),("content","ABC")]))
        >>> server.show("send")
        {"addr":66,"content":"ABC"}
        */
        if (type_struct == "send") {
            return Some<HashMap<String, Any>>(this.send_struct)
        } else if (type_struct == "receive") {
            return Some<HashMap<String, Any>>(this.receive_struct)
        } else {
            return None<HashMap<String, Any>>
        }
    }
}

import std.collection.*

interface Equatable<T> {
    operator func == (that: T): Bool
    operator func != (that: T): Bool
}

class Item <: Equatable<Item> {
    var price: Float64
    var quantity: Int64

    public init(price: Float64, quantity: Int64) {
        this.price = price
        this.quantity = quantity
    }

    public override operator func != (that: Item): Bool {
        return this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Item): Bool {
        return this.price == that.price && this.quantity == that.quantity
    }
}

class ShoppingCart {
    /*
    The class manages items, their prices, quantities, and allows to for add, removie, view items, and calculate the total price.
    */

    let items: HashMap<String, Item>
    var _total: Float64

    public init() {
        /*
        Initialize the items representing the shopping list as an empty dictionary
        */
        items = HashMap<String, Item>()
        _total = 0.0
    }

    public func add_item(item: String, price: Float64, quantity!: Int64 = 1): Unit {
        /*
        Add item information to the shopping list items, including price and quantity. The default quantity is 1
        :param item: String, Item to be added
        :param price: Float64, The price of the item
        :param quantity:Int64, The number of items, defaults to 1
        :return:Unit
        >>> shoppingcart = ShoppingCart()
        >>> shoppingcart.add_item("apple", 1.0, quantity: 5)
        this.items = {"apple": Item(1.0, 5)}
        */
        if (quantity <= 0) {
            return
        }
        let opt = items.get(item)
        match (opt) {
            case Some<Item>(it) => {
                // Keep existing price; add to quantity
                it.quantity = it.quantity + quantity
                _total = _total + it.price * quantity
            }
            case None<Item> => {
                let newItem = Item(price, quantity)
                items.add(item, newItem)
                _total = _total + price * quantity
            }
        }
    }

    public func remove_item(item: String, quantity!: Int64 = 1): Unit {
        /*
        Subtract the specified quantity of item from the shopping list items
        :param item:String, Item to be subtracted in quantity
        :param quantity:Int64, Quantity to be subtracted
        :return:Unit
        >>> shoppingcart.add_item("apple", 1.0, quantity: 5)
        >>> shoppingcart.remove_item("apple", quantity: 3)
        this.items = {"apple": Item(1.0, 2)}
        */
        if (quantity <= 0) {
            return
        }
        let opt = items.get(item)
        match (opt) {
            case Some<Item>(it) => {
                if (quantity >= it.quantity) {
                    _total = _total - it.price * it.quantity
                    items.remove(item)
                } else {
                    it.quantity = it.quantity - quantity
                    _total = _total - it.price * quantity
                }
            }
            case None<Item> => { }
        }
    }

    public func view_items(): HashMap<String, Item> {
        /*
        Return the current shopping list items
        :return:HashMap<String, Item>, the current shopping list items
        >>> shoppingcart.add_item("apple", 1.0, quantity: 5)
        >>> shoppingcart.remove_item("apple", quantity: 3)
        >>> shoppingcart.view_items()
        {"apple":Item(1.0, 2)}
        */
        items
    }

    public func total_price(): Float64 {
        /*
        Calculate the total price of all items in the shopping list, which is the quantity of each item multiplied by the price
        :return:Float64, the total price of all items in the shopping list
        >>> shoppingcart = ShoppingCart()
        >>> shoppingcart.add_item("apple", 1.0, quantity: 5)
        >>> shoppingcart.add_item("banana", 2.0, quantity: 3)
        >>> shoppingcart.total_price()
        11.0
        */
        _total
    }
}

import std.collection.*

class SignInSystem {

    /*
    This is a class as sign in system, including adding users, signing in/out, checking sign-in status, and retrieving signed-in/not signed-in users.
    */

    let users: HashMap<String, Bool>
    let usernames: ArrayList<String>
    var total_users: Int64
    var signed_in_count: Int64

    public init() {
        /*
        Initialize the sign-in system.
        */
        users = HashMap<String, Bool>()
        usernames = ArrayList<String>([])
        total_users = 0
        signed_in_count = 0
    }

    public func add_user(username: String): Bool {
        /*
        Add a user to the sign-in system if the user wasn't in the this.users.
        And the initial state is false.
        :param username: String, the username to be added.
        :return: Bool, true if the user is added successfully, false if the user already exists.
        >>> signInSystem.add_user("mike")
        true
        >>> signInSystem.add_user("mike")
        false
        */
        let existed = users.get(username)
        match (existed) {
            case Some<Bool>(_ ) => {
                return false
            }
            case None<Bool> => {
                users.add(username, false)
                usernames.add(username, at: usernames.size)
                total_users = total_users + 1
                return true
            }
        }
    }

    public func sign_in(username: String): Bool {
        /*
        Sign in a user if the user was in the this.users and change the state to true.
        :param username: String, the username to be signed in.
        :return: Bool, true if the user is signed in successfully, false if the user does not exist.
        >>> signInSystem.sign_in("mike")
        true
        >>> signInSystem.sign_in("mik")
        false
        */
        let existed = users.get(username)
        match (existed) {
            case Some<Bool>(state) => {
                if (!state) {
                    users.add(username, true)
                    signed_in_count = signed_in_count + 1
                }
                return true
            }
            case None<Bool> => {
                return false
            }
        }
    }

    public func check_sign_in(username: String): Bool {
        /*
        Check if a user is signed in.
        :param username: String, the username to be checked.
        :return: Bool, true if the user is signed in, false if the user does not exist or is not signed in.
        >>> signInSystem.check_sign_in("jack")
        false
        >>> signInSystem.add_user("jack")
        >>> signInSystem.check_sign_in("jack")
        >>> signInSystem.sign_in("jack")
        >>> signInSystem.check_sign_in("jack")
        true
        */
        let opt = users.get(username)
        let state: Bool = opt ?? false
        return state
    }

    public func all_signed_in(): Bool {
        /*
        Check if all users are signed in.
        :return: Bool, true if all users are signed in, false otherwise.
        >>> signInSystem.add_user("jack")
        true
        >>> signInSystem.sign_in("jack")
        >>> signInSystem.all_signed_in()
        true
        */
        return total_users == signed_in_count
    }

    public func all_not_signed_in(): ArrayList<String> {
        /*
        Get a list of usernames that are not signed in.
        :return: ArrayList<String>, a list of usernames that are not signed in.
        >>> signInSystem = SignInSystem()
        >>> signInSystem.add_user("a")
        true
        >>> signInSystem.add_user("b")
        true
        >>> signInSystem.all_not_signed_in()
        ['a', 'b']
        */
        let res = ArrayList<String>([])
        for (i in 0..usernames.size) {
            let name = usernames[i]
            let signed: Bool = users.get(name) ?? false
            if (!signed) {
                res.add(name, at: res.size)
            }
        }
        return res
    }
}

