class Exception {
    let message: String
    public init(message: String) {
        this.message = message
    }
}

class Parser {

    /*
    This class is used to parse the expression to get the answer
    params: expression, String
    >>> parser = Parser("4+3+6+6")
    >>> parser.parse()
    19
    */

    let expr: String
    var pos: Int64
    var ch: Rune

    public init(expr: String) {
        this.expr = expr
        this.pos = -1
        this.ch = r'x'
        this.next_char()
    }

    public func next_char(): Unit {
        this.pos += 1
        if (this.pos < this.expr.size) {
            this.ch = Rune(this.expr[this.pos])
        } else {
            this.ch = r'x'
        }
    }

    public func eat(char_to_eat: Rune): Bool {
        while (this.ch == r' ') {
            this.next_char()
        }
        if (this.ch == char_to_eat) {
            this.next_char()
            return true
        }
        return false
    }

    public func parse(): Int64 {
        let x = this.parse_expression()
        if (this.pos < this.expr.size) {
            throw Exception("Unexpected: ${this.ch}")
        }
        return x
    }

    public func parse_expression(): Int64 {
        var x = this.parse_term()
        while (true) {
            if (this.eat(r'+')) {
                x += this.parse_term()
            } else if (this.eat(r'-')) {
                x -= this.parse_term()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_term(): Int64 {
        var x = this.parse_factor()
        while (true) {
            if (this.eat(r'*')) {
                x *= this.parse_factor()
            } else if (this.eat(r'/')) {
                x /= this.parse_factor()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_factor(): Int64 {
        if (this.eat(r'+')) {
            return this.parse_factor()
        }
        if (this.eat(r'-')) {
            return -this.parse_factor()
        }

        var x = 0
        var start_pos = this.pos

        if (this.eat(r'(')) {
            x = this.parse_expression()
            this.eat(r')')
        } else if (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
            while (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
                this.next_char()
            }
            x = Int64.parse(this.expr[start_pos..this.pos])
        } else {
            if (this.ch != r'x') {
                throw Exception("Unexpected: ${this.ch}")
            } else {
                throw Exception("Unexpected end of expression")
            }
        }
        return x
    }
}

class TwentyFourPointGame {

    /*
    This is a game of twenty-four points, which provides to generate four numbers and check whether player's expression is equal to 24.
    */

    var nums: ArrayList<Int64>

    public init() {
        this.nums = ArrayList<Int64>()
    }

    public func _generate_cards(): Unit {
        /*
        Generate random numbers between 1 and 9 for the cards.
        */
        this.nums = ArrayList<Int64>()
        let rng = Random()
        for (i in 0..4) {
            // Conservatively assume nextInt(min, max) returns a value in [min, max)
            let v = rng.nextInt(1, 10)
            this.nums.add(v, at: this.nums.size)
        }
    }

    public func get_my_cards(): ArrayList<Int64> {
        /*
        Get a list of four random numbers between 1 and 9 representing the player's cards.
        :return: ArrayList<Int64>, representing the player's cards
        >>> game = TwentyFourPointGame()
        >>> game.get_my_cards()
        */
        this._generate_cards()
        return this.nums
    }

    public func answer(expression: String): Bool {
        /*
        Check if a given mathematical expression using the cards can evaluate to 24.
        :param expression: String, mathematical expression using the cards
        :return: Bool, true if the expression evaluates to 24, false otherwise
        >>> game = TwentyFourPointGame()
        >>> game.nums = [4, 3, 6, 6]
        >>> ans = "4*3+6+6"
        >>> ret = game.answer(ans)
        true
        */
        // Validate the expression uses exactly these cards (single-digit 1..9), by multiset comparison.
        var required = HashMap<Int64, Int64>([])
        for (i in 0..this.nums.size) {
            let k = this.nums[i]
            let cur = required.get(k) ?? 0
            required.add(k, cur + 1)
        }

        var used = HashMap<Int64, Int64>([])
        var digits_count: Int64 = 0
        for (i in 0..expression.size) {
            let ch = Rune(expression[i])
            if (ch.isAsciiNumber()) {
                let d = Int64.parse(expression[i..i + 1]) // single digit
                if (d == 0) {
                    return false
                }
                digits_count += 1
                let cur2 = used.get(d) ?? 0
                used.add(d, cur2 + 1)
            }
        }

        if (digits_count != 4) {
            return false
        }

        // Compare multisets
        // Ensure every required key matches used counts and no extra digits were used
        for (i in 0..this.nums.size) {
            let k = this.nums[i]
            let need = required.get(k) ?? 0
            let got = used.get(k) ?? 0
            if (need != got) {
                return false
            }
        }
        // Also ensure there are no digits outside required
        // (Check each used key appears in required with same count)
        // Since we don't have iteration over map keys specified, approximate by re-scanning expression:
        for (i in 0..expression.size) {
            let ch = Rune(expression[i])
            if (ch.isAsciiNumber()) {
                let d = Int64.parse(expression[i..i + 1])
                let need2 = required.get(d) ?? 0
                let got2 = used.get(d) ?? 0
                if (need2 == 0 || got2 > need2) {
                    return false
                }
            }
        }

        return this.evaluate_expression(expression)
    }

    public func evaluate_expression(expression: String): Bool {
        /*
        Evaluate a mathematical expression and check if the result is 24.
        :param expression: String, mathematical expression
        :return: Bool, true if the expression evaluates to 24, false otherwise
        >>> game = TwentyFourPointGame()
        >>> nums = [4, 3, 6, 6]
        >>> ans = "4*3+6+6"
        >>> ret = game.evaluate_expression(ans)
        true
        */
        try {
            let parser = Parser(expression)
            let result = parser.parse()
            return result == 24
        } catch (e) {
            return false
        }
    }
}

import std.collection.*

class URLHandler {

    /*
    The class supports to handle URLs, including extracting the scheme, host, path, query parameters, and fragment.
    */

    let url: String

    public init(url: String) {
        /*
        Initialize URLHandler's URL
        */
        this.url = url
    }

    public func get_scheme(): Option<String> {
        /*
        get the scheme of the URL
        :return: Option<String>, If successful, return the scheme of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_scheme()
        "https"
        */
        let s = this.url
        let pos = s.indexOf("://")
        if (pos == -1) {
            return None<String>
        }
        let scheme = s.substring(0, pos)
        return Some<String>(scheme)
    }

    public func get_host(): Option<String> {
        /*
        Get the second part of the URL, which is the host domain name
        :return: Option<String>, If successful, return the host domain name of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_host()
        "www.baidu.com"
        */
        let s = this.url
        let schemePos = s.indexOf("://")
        var hostStart = 0
        if (schemePos != -1) {
            hostStart = schemePos + 3
        } else {
            hostStart = 0
        }

        let slashPos = s.indexOf("/", hostStart)
        let qPos = s.indexOf("?", hostStart)
        let hashPos = s.indexOf("#", hostStart)

        var hostEnd = -1
        if (slashPos != -1) {
            hostEnd = slashPos
        }
        if (qPos != -1 && (hostEnd == -1 || qPos < hostEnd)) {
            hostEnd = qPos
        }
        if (hashPos != -1 && (hostEnd == -1 || hashPos < hostEnd)) {
            hostEnd = hashPos
        }

        let host = if (hostEnd == -1) { s.substring(hostStart) } else { s.substring(hostStart, hostEnd) }
        return Some<String>(host)
    }

    public func get_path(): Option<String> {
        /*
        Get the third part of the URL, which is the address of the resource
        :return: Option<String>, If successful, return the address of the resource of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_path()
        "/s?wd=aaa&rsv_spt=1#page"
        */
        let s = this.url
        let schemePos = s.indexOf("://")
        var afterHost = 0
        if (schemePos != -1) {
            afterHost = schemePos + 3
        }

        let slashPos = s.indexOf("/", afterHost)
        if (slashPos == -1) {
            return None<String>
        }
        let pathAndMore = s.substring(slashPos)
        return Some<String>(pathAndMore)
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        /*
        Get the request parameters for the URL
        :return: Option<HashMap<String, String>>, If successful, return the request parameters of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_query_params()
        {"wd": "aaa", "rsv_spt": "1"}
        */
        let s = this.url
        let qMark = s.indexOf("?")
        if (qMark == -1) {
            return None<HashMap<String, String>>
        }
        let hashAfterQ = s.indexOf("#", qMark + 1)
        let query = if (hashAfterQ == -1) { s.substring(qMark + 1) } else { s.substring(qMark + 1, hashAfterQ) }

        let parts = query.split("&")
        let params = HashMap<String, String>([])
        for (i in 0..parts.size) {
            let pair = parts[i]
            if (pair == "") {
                continue
            }
            let eq = pair.indexOf("=")
            if (eq == -1) {
                let key = pair
                let value = ""
                params.add(key, value)
            } else {
                let key = pair.substring(0, eq)
                let value = pair.substring(eq + 1)
                params.add(key, value)
            }
        }

        if (params.size == 0) {
            return None<HashMap<String, String>>
        }
        return Some<HashMap<String, String>>(params)
    }

    public func get_fragment(): Option<String> {
        /*
        Get the fragment after '#' in the URL
        :return: Option<String>, If successful, return the fragment after '#' of the URL
        >>> urlhandler = URLHandler("https://www.baidu.com/s?wd=aaa&rsv_spt=1#page")
        >>> urlhandler.get_fragment()
        "page"
        */
        let s = this.url
        let hashPos = s.indexOf("#")
        if (hashPos == -1) {
            return None<String>
        }
        let frag = s.substring(hashPos + 1)
        return Some<String>(frag)
    }
}

import std.collection.*

class UrlPath {

    /*
    The class is a utility for encapsulating and manipulating the path component of a URL, including adding nodes, parsing path strings, and building path strings with optional encoding.
    */

    let segments: ArrayList<String>
    var with_end_tag: Bool

    public init() {
        /*
        Initializes the UrlPath object with an empty list of segments and a flag indicating the presence of an end tag.
        */
        this.segments = ArrayList<String>()
        this.with_end_tag = false
    }

    public func add(segment: String): Unit {
        /*
        Adds a segment to the list of segments in the UrlPath.
        :param segment: String, the segment to add.
        >>> url_path = UrlPath()
        >>> url_path.add('foo')
        >>> url_path.add('bar')

        url_path.segments = ['foo', 'bar']
        */
        let fixed = UrlPath.fix_path(segment)
        // Only add non-empty segments; append at the end.
        let fixedRunes = fixed.toRuneArray()
        if (fixedRunes.size == 0) {
            return
        }
        this.segments.add(fixed, at: this.segments.size)
    }

    public func parse(path: String): Unit {
        /*
        Parses a given path string and populates the list of segments in the UrlPath.
        :param path: String, the path string to parse.
        >>> url_path = UrlPath()
        >>> url_path.parse('/foo/bar/')

        url_path.segments = ['foo', 'bar']
        */
        // Determine if original path ends with a slash
        let origRunes = path.toRuneArray()
        var endsWithSlash: Bool = false
        if (origRunes.size > 0) {
            if (origRunes[origRunes.size - 1] == r'/') {
                endsWithSlash = true
            }
        }
        this.with_end_tag = endsWithSlash

        // Clear existing segments
        while (this.segments.size > 0) {
            this.segments.remove(at: this.segments.size - 1)
        }

        // Normalize path (remove leading/trailing slashes)
        let fixed = UrlPath.fix_path(path)
        let runes = fixed.toRuneArray()
        if (runes.size == 0) {
            return
        }

        // Split by '/' and ignore empty segments (handles repeated slashes)
        var current: String = ""
        var hasChars: Bool = false
        var i: Int64 = 0
        while (i < runes.size) {
            let ch = runes[i]
            if (ch == r'/') {
                if (hasChars) {
                    this.segments.add(current, at: this.segments.size)
                    current = ""
                    hasChars = false
                }
            } else {
                current = "${current}${ch}"
                hasChars = true
            }
            i = i + 1
        }
        if (hasChars) {
            this.segments.add(current, at: this.segments.size)
        }
    }

    public static func fix_path(path: String): String {
        /*
        Fixes the given path string by removing leading and trailing slashes.
        :param path: String, the path string to fix.
        :return: String, the fixed path string.
        >>> url_path = UrlPath()
        >>> url_path.fix_path('/foo/bar/')
        'foo/bar'
        */
        let runes = path.toRuneArray()
        let n: Int64 = runes.size
        if (n == 0) {
            return ""
        }

        var start: Int64 = 0
        while (start < n && runes[start] == r'/') {
            start = start + 1
        }
        if (start >= n) {
            return ""
        }

        var end: Int64 = n - 1
        while (end >= start && runes[end] == r'/') {
            end = end - 1
        }

        var res: String = ""
        var i: Int64 = start
        while (i <= end) {
            res = "${res}${runes[i]}"
            i = i + 1
        }
        res
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    /*
    The class provides vector operations, including calculating similarity, cosine similarities, average similarity, and IDF weights.
    */

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let n1 = vector_1.size
        let n2 = vector_2.size
        let n = if (n1 < n2) { n1 } else { n2 }
        if (n == 0) {
            return 0.0
        }

        var dot: Float64 = 0.0
        var norm1_sq: Float64 = 0.0
        var norm2_sq: Float64 = 0.0
        for (i in 0..n) {
            let a = vector_1[i]
            let b = vector_2[i]
            dot = dot + a * b
            norm1_sq = norm1_sq + a * a
            norm2_sq = norm2_sq + b * b
        }
        let denom = sqrt(norm1_sq) * sqrt(norm2_sq)
        if (denom == 0.0) {
            return 0.0
        }
        return dot / denom
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let res = ArrayList<Float64>([])
        let m = vectors_all.size
        for (i in 0..m) {
            let v = vectors_all[i]
            let n1 = vector_1.size
            let n2 = v.size
            let n = if (n1 < n2) { n1 } else { n2 }
            if (n == 0) {
                res.add(0.0, at: res.size)
            } else {
                var dot: Float64 = 0.0
                var norm1_sq: Float64 = 0.0
                var norm2_sq: Float64 = 0.0
                for (j in 0..n) {
                    let a = vector_1[j]
                    let b = v[j]
                    dot = dot + a * b
                    norm1_sq = norm1_sq + a * a
                    norm2_sq = norm2_sq + b * b
                }
                let denom = sqrt(norm1_sq) * sqrt(norm2_sq)
                let sim = if (denom == 0.0) { 0.0 } else { dot / denom }
                res.add(sim, at: res.size)
            }
        }
        return res
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        let c1 = vector_list_1.size
        let c2 = vector_list_2.size
        if (c1 == 0 || c2 == 0) {
            return 0.0
        }

        let dim1 = if (c1 > 0) { vector_list_1[0].size } else { 0 }
        let dim2 = if (c2 > 0) { vector_list_2[0].size } else { 0 }
        let dim = if (dim1 < dim2) { dim1 } else { dim2 }
        if (dim == 0) {
            return 0.0
        }

        // mean of list 1
        let mean1 = ArrayList<Float64>([])
        for (i in 0..dim) {
            mean1.add(0.0, at: i)
        }
        for (i in 0..c1) {
            let v = vector_list_1[i]
            let use = if (v.size < dim) { v.size } else { dim }
            for (j in 0..use) {
                mean1[j] = mean1[j] + v[j]
            }
        }
        for (j in 0..dim) {
            mean1[j] = mean1[j] / (c1 as Float64)
        }

        // mean of list 2
        let mean2 = ArrayList<Float64>([])
        for (i in 0..dim) {
            mean2.add(0.0, at: i)
        }
        for (i in 0..c2) {
            let v = vector_list_2[i]
            let use = if (v.size < dim) { v.size } else { dim }
            for (j in 0..use) {
                mean2[j] = mean2[j] + v[j]
            }
        }
        for (j in 0..dim) {
            mean2[j] = mean2[j] / (c2 as Float64)
        }

        return VectorUtil.similarity(mean1, mean2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result = HashMap<String, Float64>([])
        let keys = number_dict.keys()
        let numerator = (total_num as Float64) + 1.0
        for (i in 0..keys.size) {
            let key = keys[i]
            let count = number_dict[key]
            let value = log(numerator / (count + 1.0))
            result.add(key, value)
        }
        return result
    }
}

