class Weather {
    let weather: String
    let temperature: Float64
    let temperature_units: String

    public init(weather: String, temperature: Float64, temperature_units: String) {
        this.weather = weather
        this.temperature = temperature
        this.temperature_units = temperature_units
    }
}

class WeatherSystem {
    /*
    This is a class representing a weather system that provides functionality to query weather information for a specific city and convert temperature units between Celsius and Fahrenheit.
    */

    var temperature: Float64
    var weather: String
    var city: String
    var weather_list: HashMap<String, Weather>

    public init(city: String) {
        /*
        Initialize the weather system with a city name.
        */
        this.temperature = Float64.NaN
        this.weather = ""
        this.city = city
        this.weather_list = HashMap<String, Weather>()
    }

    public func query(weather_list: HashMap<String, Weather>, tmp_units!: String = "celsius"): Option<(Float64, String)> {
        /*
        Query the weather system for the weather and temperature of the city, and convert the temperature units based on the input parameter.
        :param weather_list: a dictionary of weather information for different cities, HashMap<String, Weather>.
        :param tmp_units: the temperature units to convert to, String ("celsius" or "fahrenheit").
        :return: the temperature and weather of the city, Option<(Float64, String)>.
        */
        this.weather_list = weather_list

        let opt = weather_list.get(this.city)
        match (opt) {
            case Some<Weather>(w) => {
                let from_units = w.temperature_units
                var temp: Float64 = w.temperature

                if ((from_units == "celsius") && (tmp_units == "fahrenheit")) {
                    temp = temp * 9.0 / 5.0 + 32.0
                } else if ((from_units == "fahrenheit") && (tmp_units == "celsius")) {
                    temp = (temp - 32.0) * 5.0 / 9.0
                } else if (!((tmp_units == "celsius") || (tmp_units == "fahrenheit"))) {
                    return None<(Float64, String)>
                }

                this.temperature = temp
                this.weather = w.weather
                return Some<(Float64, String)>((temp, w.weather))
            }
            case _ => {
                return None<(Float64, String)>
            }
        }
    }

    public func set_city(city: String): Unit {
        /*
        Set the city of the weather system.
        :param city: the city to set, String.
        :return: Unit
        */
        this.city = city
    }

    public func celsius_to_fahrenheit(): Float64 {
        /*
        Convert the temperature from Celsius to Fahrenheit.
        :return: the temperature in Fahrenheit, Float64.
        */
        this.temperature * 9.0 / 5.0 + 32.0
    }

    public func fahrenheit_to_celsius(): Float64 {
        /*
        Convert the temperature from Fahrenheit to Celsius.
        :return: the temperature in Celsius, Float64.
        */
        (this.temperature - 32.0) * 5.0 / 9.0
    }
}

import std.collection.*

class Words2Numbers {

    /*
    The class provides a text-to-number conversion utility, allowing conversion of written numbers (in words) to their numerical representation.
    */

    let numwords: HashMap<String, (Int64, Int64)>
    let units: ArrayList<String>
    let tens: ArrayList<String>
    let scales: ArrayList<String>
    let ordinal_words: HashMap<String, Int64>
    let ordinal_endings: ArrayList<(String, String)>

    public init() {
        /*
        Initialize the word lists and dictionaries required for conversion
        */
        this.numwords = HashMap<String, (Int64, Int64)>()
        this.units = ArrayList<String>(["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"])
        this.tens = ArrayList<String>(["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"])
        this.scales = ArrayList<String>(["hundred", "thousand", "million", "billion", "trillion"])

        // basic words
        this.numwords["and"] = (1, 0)
        for (idx in 0..this.units.size) {
            this.numwords[this.units[idx]] = (1, idx)
        }
        for (idx in 0..this.tens.size) {
            let t = this.tens[idx]
            if (t != "") {
                this.numwords[t] = (1, idx * 10)
            }
        }
        // scales
        this.numwords["hundred"] = (100, 0)
        this.numwords["thousand"] = (1000, 0)
        this.numwords["million"] = (1000000, 0)
        this.numwords["billion"] = (1000000000, 0)
        this.numwords["trillion"] = (1000000000000, 0)

        this.ordinal_words = HashMap<String, Int64>([
            ("first", 1), ("second", 2), ("third", 3),
            ("fifth", 5), ("eighth", 8), ("ninth", 9),
            ("twelfth", 12)
        ])
        this.ordinal_endings = ArrayList<(String, String)>([
            ("ieth", "y"), ("th", "")
        ])
    }

    public func text2int(textnum: String): String {
        /*
        Convert the word string to the corresponding integer string
        :param textnum: String, the word string to be converted
        :return: String, the final converted integer string
        >>> w2n = Words2Numbers()
        >>> w2n.text2int("thirty-two")
        "32"
        */
        let tokens = this.tokenize(textnum)
        var current: Int64 = 0
        var result: Int64 = 0

        for (i in 0..tokens.size) {
            let original = tokens[i]
            let wordOpt = this.normalizeToKnown(original)
            match (wordOpt) {
                case Some<String>(w) => {
                    let entryOpt = this.numwords.get(w)
                    match (entryOpt) {
                        case Some<(Int64, Int64)>(pair) => {
                            let scale = pair[0]
                            let increment = pair[1]
                            if (scale == 1) {
                                current = current + increment
                            } else if (scale == 100) {
                                // "hundred"
                                if (current == 0) {
                                    current = 1
                                }
                                current = current * scale
                            } else {
                                // thousand and above
                                if (current == 0) {
                                    result = result + scale
                                } else {
                                    result = result + current * scale
                                }
                                current = 0
                            }
                        }
                        case _ => {
                            // should not reach here due to normalizeToKnown
                        }
                    }
                }
                case _ => {
                    // Unrecognized token; treat as 0 effect or throw; here we just return "0"
                    // to keep function total. Alternatively, could throw if desired.
                    return "0"
                }
            }
        }
        let total = result + current
        return "${total}"
    }

    public func is_valid_input(textnum: String): Bool {
        /*
        Check if the input text contains only valid words that can be converted into numbers.
        :param textnum: The input text containing words representing numbers.
        :return: true if input is valid, false otherwise.
        >>> w2n = Words2Numbers()
        >>> w2n.is_valid_input("thirty-two")
        true
        */
        let tokens = this.tokenize(textnum)
        for (i in 0..tokens.size) {
            let ok = match (this.normalizeToKnown(tokens[i])) {
                case Some<String>(_) => true
                case _ => false
            }
            if (!ok) {
                return false
            }
        }
        return true
    }

    // Helper: split input into tokens, using space and hyphen as delimiters.
    private func tokenize(s: String): ArrayList<String> {
        var tokens = ArrayList<String>()
        var current = ""
        let it = s.runes()
        for (/* no index here, iterate runes */) {
            let maybe = it.next()
            match (maybe) {
                case Some<Rune>(r) => {
                    if (this.isSpace(r) || this.isHyphen(r)) {
                        if (current != "") {
                            tokens.add(current)
                            current = ""
                        }
                    } else {
                        current = current + this.runeToString(r)
                    }
                }
                case _ => {
                    break
                }
            }
        }
        if (current != "") {
            tokens.add(current)
        }
        return tokens
    }

    private func isSpace(r: Rune): Bool {
        return r == r' ' || r == r'\t' || r == r'\n'
    }

    private func isHyphen(r: Rune): Bool {
        return r == r'-'
    }

    private func runeToString(r: Rune): String {
        return "${r}"
    }

    // Normalize a token to a known cardinal word present in numwords, if possible.
    private func normalizeToKnown(word: String): Option<String> {
        // Directly known
        match (this.numwords.get(word)) {
            case Some<(Int64, Int64)>(_) => {
                return Some<String>(word)
            }
            case _ => { /* continue */ }
        }

        // Irregular ordinal words: map to their cardinal unit word
        match (this.ordinal_words.get(word)) {
            case Some<Int64>(n) => {
                if (n >= 0 && n < this.units.size) {
                    return Some<String>(this.units[n])
                } else {
                    // Out of range (shouldn't happen for given list)
                    return None<String>
                }
            }
            case _ => { /* continue */ }
        }

        // Regular ordinal endings: try to strip and replace suffix, then recheck
        for (i in 0..this.ordinal_endings.size) {
            let ending = this.ordinal_endings[i][0]
            let repl = this.ordinal_endings[i][1]
            if (this.endsWith(word, ending)) {
                let base = this.replaceSuffix(word, ending, repl)
                match (this.numwords.get(base)) {
                    case Some<(Int64, Int64)>(_) => {
                        return Some<String>(base)
                    }
                    case _ => { /* continue */ }
                }
            }
        }

        return None<String>
    }

    private func endsWith(s: String, suffix: String): Bool {
        let sr: Array<Rune> = s.toRuneArray()
        let tr: Array<Rune> = suffix.toRuneArray()
        let n = sr.size
        let m = tr.size
        if (m > n) { return false }
        for (i in 0..m) {
            if (sr[n - m + i] != tr[i]) {
                return false
            }
        }
        return true
    }

    private func replaceSuffix(s: String, suffix: String, replacement: String): String {
        if (!this.endsWith(s, suffix)) {
            return s
        }
        let sr: Array<Rune> = s.toRuneArray()
        let m = suffix.toRuneArray().size
        let prefixLen = sr.size - m
        var res = ""
        for (i in 0..prefixLen) {
            res = res + this.runeToString(sr[i])
        }
        res = res + replacement
        return res
    }
}
